"1l4":"20+ sessions de peering ({n})",
"1l5":"POP sur 3+ continents",
"1l6":"servir 1,5 Tbps ({v})",
"1l7":"Canicule à 45 °C à {city} : le réseau a délesté, les groupes froids ont lâché, et le groupe électrogène de {dc} aussi.",
"1l8":"Une pelleteuse a coupé l’anneau métropolitain entre tes deux sites à {city}. En fait, les deux chemins de fibre passaient par la même rue.",
"1l9":"Un black-out a frappé {city} et ton POP n’a pas de groupe électrogène. Tous les autres réseaux ici en ont un. Achètes-en un.",
