"2vo":"Les modèles frontière arrivent au niveau {lv}.",
"2vp":"Ton propre modèle frontière, entraîné entre {a}, {b} et {c} : {g} sur chacun de deux tronçons pendant {n} semaines, chaque tronçon sous sa limite de latence. GPU et électricité coûtent {mo}/mois pendant l'entraînement.",
