"2yi":"Lancer Tubular · {cost}",
"2yj":"Tubular est en ligne. Vidéos de chats, unboxings et boucles de pluie de dix heures : son audience monte sur {days} jours. Les edge stacks à tes portes d'entrée devront en porter l'essentiel.",
"2yk":"Tubular : {g} de vidéo, {p} de son audience · {e} servi par des edge stacks près des utilisateurs.",
"2yl":"Tubular est déjà en ligne.",
"2ym":"Tubular se lance à partir du niveau {lv}.",
"2yn":"Lance-toi d'abord dans un pays : Tubular a besoin d'utilisateurs.",
"2yo":"Ta propre plateforme vidéo, Tubular : une fois lancée, la vidéo tirera {x} fois ce que tirent tes utilisateurs aujourd'hui. Jusqu'à {p} peut venir des edge stacks à tes portes d'entrée, et un Gbps de vidéo rapporte {r} d'un autre trafic : elle ne paie que servie près et pas cher.",
"2yp":"Gagne en Hyperscaler : Cloud Nine.",
"2yq":"Transit ? Connais pas",
"2yr":"En Hyperscaler, passe sans transit et peere avec chaque Tier 1.",
"2ys":"Entre régions à la pointe : {g} sur {max}",
"2yt":"Ton propre câble sous-marin à travers un océan",
"2yu":"Régions sur {n} continents sur {max}",
"2yv":"Paires de régions testées : {n} sur {max}",
"2yw":"Cloud Nine",
"2yx":"Un entraînement d'IA à l'heure",
"2yy":"Livre l'entraînement d'un labo d'IA avant son échéance.",
"2yz":"Un câble sous-marin à toi",
"2z":"Chicago veut en être.",
"2z0":"Prends une place dans un câble de consortium, ou pose le tien. L'équipe IA ne demande que l'Atlantique.",
"2z1":"Réussir un exercice de basculement",
"2z2":"Bascule exprès une région vers sa réplique pendant une journée, sans que personne ne le remarque.",
"2z3":"Répliquer entre deux régions",
"2z4":"Avec deux régions en service, chacune copie ce qu'écrivent ses utilisateurs vers l'autre via ton backbone.",
"2z5":"Survivre à la panne d'une région",
"2z6":"Perds vraiment une région sans perdre de données, pendant que sa réplique sert bien tout le monde.",
"2z7":"Des régions sur cinq continents, un exercice réussi pour chaque paire de régions, ton propre câble à travers un océan et 10 Tbps entre régions à la pointe.",
"2z8":"{name} a des régions sur {n} continents, chaque paire testée, sa propre fibre sous un océan et {g} entre régions à la pointe. La tête dans les nuages, les pieds sur la fibre.",
"2z9":"Cloud Nine, atteint le {date}.",
"2za":"Louer un groupe électrogène",
"2zb":"Un pigeon voyageur a battu un de tes liens lors d’un test de latence informel. Le moral est en berne. Le débit va bien.",
"2zc":"Un client a ouvert un ticket P1 : « Internet est lent ». En pièce jointe, une photo de son routeur, débranché.",
"2zd":"Une oie a attaqué le technicien en route vers ta cabane d’amplis. L’oie a gagné. Intervention reportée, rien de cassé.",
"2ze":"Une seconde intercalaire a convaincu un de tes routeurs qu’on est en 1970. L’uptime affiche moins 56 ans. Le trafic va bien.",
"2zf":"Une route que tu as retirée en année 1 est encore visible quelque part sur Internet. Personne ne sait où. Tout va bien. Probablement.",
"2zg":"Une réunion de deux heures sur les hostnames des routeurs s’est conclue par un vote pour « router-final-v2-NEW ».",
"2zh":"Un auditeur a demandé un schéma réseau. Tu lui as envoyé la carte du jeu. Il l’a validée.",
