"339":"Les contrats durent de un à cinq ans, les paires de fibre de dix à vingt. À l'échéance, la plupart renouvellent au prix du marché du jour et les clients satisfaits grossissent souvent. Certains partent, et pas toujours à cause de vous.",
"33a":"Construire en Chine continentale exige une coentreprise et une licence d’opérateur. Ouvre {city} pour faire la demande.",
