"33u":"épuisé pour {n} jours",
"33v":"Les frontières autour du Qatar sont fermées : un lien entre Doha et l'Arabie saoudite ou les Émirats restera éteint jusqu'à ce que les voisins se réconcilient.",
"33w":"Le litige sur le permis d’atterrissement à {city} bloque les nouveaux liens sous-marins pendant encore {n} jours.",
"33x":"Les longueurs d’onde se louent à tarif mensuel fixe. Plus c’est gros et long, plus c’est cher, et le sous-marin coûte 1,8×. Le premier mois est à payer tout de suite.",
