"341":"Une brouille diplomatique a fermé les frontières autour du Qatar : tous les liens entre Doha et l'Arabie saoudite ou les Émirats sont coupés. Rien à réparer, et pas de réparation express pour la diplomatie : passez par le long chemin, par la mer.",
"342":"Un lien en attente ne porte du trafic que lorsque les autres liens entre ces villes sont pleins ou coupés.",
"343":"Le coût d’un lien, c’est sa longueur en km plus 60, fois un multiplicateur. Le trafic prend le chemin au coût total le plus bas.",
"344":"Un site de régénération reconvertit la lumière en bits à mi-chemin et la renvoie toute fraîche, donc les optiques n’ont qu’à atteindre le site suivant. Chacun demande une carte de régénération par canal allumé. {price}/mois par site pour l’abri.",
