"35e":"Perdre tes avantages exclusifs ?",
"35f":"Perdu en route",
"35g":"La Chine continentale joue selon ses propres règles. {list} et d’autres services étrangers y sont bloqués, donc les utilisateurs atteignent surtout des réseaux chinois. Le trafic qui passe la frontière perd environ {pct} en filtrage et congestion, sauf s’il emprunte une route premium : du transit CN-Too ou un circuit transfrontalier premium (tous deux vendus uniquement à Hong Kong), ou un PNI avec un réseau chinois. Le revenu par utilisateur est plus faible ici.",
"35h":"Le broker laissera cette route tranquille : rien n’y sera vendu à la livraison de la fibre.",
"35i":"Le broker laisse tranquille toute la route entre {a} et {b} : ta fibre active dès maintenant, et cette fibre à sa livraison.",
"35j":"Le broker commerce déjà sur ta fibre active entre {a} et {b}, et ajoute cette fibre le jour de sa livraison. L'interrupteur vaut pour toute la route : l'éteindre arrête aussi tout de suite le commerce sur la fibre active.",
