"37k":{"one":"Partage une tranchée avec {n} autre lien. Une coupure et ils tombent tous.","other":"Partage une tranchée avec {n} autres liens. Une coupure et ils tombent tous."},
"37l":"Simple instantané : seul le lien choisi tombe. Les autres liens du même câble, de la même tranchée ou du même fabric restent en place. Les pannes et règles de routage en cours s’appliquent toujours. Ni le temps, ni l’argent, ni la partie ne changent.",
"37m":"Vendus en waves gérées",
"37n":"Des optiques et des cartes d’ampli de rechange sur l’étagère transforment des pannes matérielles de plusieurs jours en remplacements d’une journée.",
