"37x":"Cette pelleteuse gagne.",
"37y":"Cette fibre est éteinte. Ajoute des optiques ci-dessous pour transporter du trafic.",
"37z":"C’est le seul lien entre ces villes. Ajoutes-en un parallèle, ou un chemin via une autre ville.",
