"38f":"construite par toi",
"38g":"Ton propre fabric · {name}",
"38h":"Tes routeurs choisissent le chemin le moins coûteux. Augmente la métrique pour pousser le trafic vers d’autres chemins. « Secours seul » le laisse au repos tant que le reste fonctionne. Choisis Perso pour fixer ton propre multiplicateur ou coût. S’applique à tous les liens entre ces deux villes.",
"38i":"Ton trafic qui passe la frontière",
"38j":"Ta longueur d’onde a été vendue avant que le propriétaire du câble ne le réingénie, donc elle continue de tourner.",
"38k":"À toi",
