"397":"<b>Tu as fondé {ix} !</b><br>Des réseaux vont le rejoindre peu à peu et te payer leurs ports. Les membres open font du peering avec toi gratuitement.",
"398":"Une coopérative fibre pour une seule vallée. Chaque membre possède un mètre de câble.",
"399":"Un riche mélange de tout ce que les pêcheurs ont ramené.",
"39a":"Mille minuscules réseaux sociaux sur un seul rack.",
"39b":"Le plus grand réseau de l’Alaska, d’Anchorage aux Aléoutiennes. A racheté la fibre arctique en 2026 et ne fait du peering qu’à Seattle.",
"39c":"Le vieil opérateur téléphonique de l’Alaska et, pour l’instant, le seul membre de son propre IX.",
"39d":"Un FAI géré depuis l’arrière-boutique d’un kebab. Le support de nuit est excellent.",
"39e":"Le câblo-opérateur du Canada atlantique, nourri au homard et aux longs hivers. Poli au téléphone, une bête à la table de peering.",
"39f":"L’opérateur du Canada atlantique, venu d’une autre planète : de la fibre vers Terre-Neuve, l’Île et le Nouveau-Brunswick.",
"39g":"Téléphone, télé et internet des Bermudes, tout depuis un bureau très occupé. La moitié de ses clients professionnels sont des réassureurs, et ils ont déjà intégré le Triangle dans leurs prix.",
"39h":"Du haut débit dans des dizaines de villes russes : peering ouvert, et pour tout le reste, euh… hum.",
"39i":"Combinaison de salle blanche obligatoire en salle serveurs.",
"39j":"Le haut débit par câble pour la moitié de la Grande-Bretagne. Rapide les bons jours.",
"39k":"Télé par câble et haut débit pour les Bahamas, avec du peering seulement à Miami, là où ça fait la fête.",
"39l":"L’opérateur historique du Cap-Vert et la porte de sortie des îles. Son CV liste chaque câble entre l’Europe, l’Afrique et le Brésil, et il le ressort à chaque réunion.",
"39m":"Pas cher, rapide et ouvert tard.",
"39n":"Hébergement pas cher et nourrissant. Demande la formule pomme de terre-fromage.",
"39o":"Coloré, bondé, et finit par t’emmener à bon port.",
"39p":"S’anime à la nuit tombée.",
"39q":"Des racks douillets sous une colline. Second petit-déjeuner à 11 h.",
"39r":"Couvre énormément de terrain vide.",
"39s":"Croustillant dehors, pas cher dedans.",
"39t":"L’opérateur d’État cubain et seul FAI. Ravi de faire du peering, si tu arrives à amener un câble jusqu’à La Havane.",
"39u":"Livré tout chaud chaque matin.",
"39v":"Hors ligne de 14 h à 17 h tous les jours. C’est voulu.",
"39w":"Ils ont creusé la tranchée eux-mêmes, champ après champ.",
"39x":"Affaire familiale depuis l’époque du modem 56k. Décroche encore le téléphone.",
"39y":"Fibre posée le long des pistes cyclables. Plus rapide sous la pluie.",
"39z":"Fibre posée sous les rails du tram pendant une équipe de nuit.",
"3a":"{a} et {b} signent : raccorde-les.",
"3a0":"Fibre tendue le long des télésièges. Latence saisonnière.",
"3a1":"La passerelle internationale des Fidji. Très maligne pour savoir où ton trafic doit passer, tant qu’il passe par Suva.",
"3a2":"Du foot, des films et un routeur qui ressemble à un vaisseau spatial.",
