"3a4":"Une télé payante française qui fait aussi du haut débit dans les îles, moins les films que tu voulais.",
"3a5":"Serveurs de jeu, boissons énergisantes et obsession du ping.",
"3a6":"S’entend avec tous les autres réseaux. Légendairement zen.",
"3a7":"Serveurs plaqués or, voiturier pour les paquets.",
"3a8":"Le seul opérateur du Groenland a du répondant : les câbles, les téléphones et les satellites, pour cinquante-six mille habitants sur la plus grande île du monde.",
"3a9":"L’opérateur historique de Guam et la porte de sortie de la moitié de la Micronésie. Les prix sont un braquage, mais personne d’autre ne vend.",
