"3ae":"L’opérateur historique d’Hawaï. Chaque forfait est servi avec deux boules de riz et une salade de macaronis.",
"3af":"Le FAI maison d’Hokkaido : la fibre de la compagnie d’électricité, enterrée sous la limite du gel.",
"3ag":"Hébergement pour toutes les trattorias familiales du Sud.",
"3ah":"Hébergement pour boutiques de surf. Fermé quand les vagues sont bonnes.",
"3ai":"Héberge tous les jeux auxquels tu joues à 2 h du matin. Déteste le jitter.",
