"3b0":"L’opérateur de Palau. Plonge avec un tuba et tu verras le câble.",
"3b1":"L’opérateur public de Papouasie-Nouvelle-Guinée : huit cents langues, un seul système de facturation.",
"3b2":"Des téléphones sur chaque île de la Papouasie-Nouvelle-Guinée aux Tonga, et du transit à vendre sur chacune.",
"3b3":"Alimenté par des rongeurs renouvelables. L’uptime dépend de l’heure du goûter.",
"3b4":"Le FAI pro de Porto Rico, qui tourne et tourne autour de l’IX de l’île.",
