"3b6":"Les racks dans la nef, le refroidissement dans la crypte. Uptime divin.",
"3b7":"Gère la poste, le téléphone et Internet en Nouvelle-Calédonie et en Polynésie française. Les paquets arrivent tamponnés, avec un croissant.",
"3b8":"Gère le réseau du village entre deux interventions.",
