"3bb":"Le haut débit des Samoa, promis avec une part de quelque chose de sucré.",
"3bc":"L’opérateur de la Saskatchewan, toujours propriété de la province et toujours plein d’histoires sur les Roughriders.",
"3bd":"Serveurs refroidis par le lac, puis recyclés pour chauffer le sauna.",
