"3bj":"L’opérateur historique de l’île et partenaire de la plupart de ses câbles. Pas encore disparu.",
"3bk":"L’opérateur de l’île, de la même couleur que la liqueur.",
"3bl":"L’opérateur des Maldives, sur des îles à un mètre au-dessus de la mer, avec des câbles vers le Sri Lanka et l’Inde.",
"3bm":"L’opérateur des Îles Marshall, à deux mètres au-dessus de la mer et fier de chaque centimètre.",
"3bn":"Le seul carrier du Nord : de la fibre le long des routes jusqu’à Whitehorse et Yellowknife, des satellites pour tout ce qui est plus loin.",
"3bo":"Le plus, c’est une taxe à l’usage. Peering payant, au gigabit.",
