"3gi":{"one":"Ton PNI avec {old} appartient maintenant à {net}.","other":"Tes {n} PNI avec {old} appartiennent maintenant à {net}."},
"3gj":"{net} fait payer le peering : attends-toi à un coût mensuel.",
"3gk":"{net} a avalé {old}.",
"3gl":"Fait désormais partie de {net} : fais du peering avec eux à la place.",
"3gm":"Un bug ou une idée ?",
"3gn":"How the Internet Works",
"3go":"Rejoins le chat du NOC",
"3gp":"Ouvrir →",
"3gq":"Notre groupe Signal : échange des captures d’écran et dispute-toi sur les politiques de peering avec d’autres joueurs. Moins de pelleteuses qu’en vrai.",
"3gr":"Dis-le-nous sur GitHub : un court formulaire pour les bugs, les idées, l’équilibrage et les traductions. On les lit tous.",
"3gs":"La version réelle, par Thomas Kjær Aabo : une carte interactive et zoomable du vrai trajet de tes paquets, du Wi-Fi à la fibre sous-marine, aujourd’hui, en 2010 et en 1995. Ce jeu invente au fur et à mesure. Celle-là, elle a tout bon.",
"3gt":"La version réelle : suis un paquet du Wi-Fi à la fibre sous-marine.",
"3gu":"Pose ton propre câble sous-marin…",
"3gv":"Ton propre câble sous-marin <small>niveau {n} ou Tier 1</small>",
"3gw":"Les classements comparent le trafic avec les autres joueurs, le trafic total, les POP, les tartes dans le ciel et le cône de clients sur les dernières 24 heures, en total ou en croissance. Jamais l'argent. Ton serveur les calcule et ta partie vérifie une ligne de temps en temps. Humains et IA ensemble ou à part, avec des filtres par région, marché d'origine, âge du réseau et plus.",
"3gx":"Accords",
"3gy":"Chaque accord est scellé pour les deux joueurs. Les serveurs le transportent mais ne peuvent pas le lire : ni l'offre, ni le prix, ni pourquoi quelqu'un a dit non. Seuls les projets de consortium ouverts à tous sont publics.",
"3gz":"Pendant leurs 30 premiers jours, les nouveaux achètent aux réseaux établis avec 25 % de remise. Un réseau établi qui fait affaire avec un nouveau touche une prime de mentor unique quand le nouveau grandit : 10 POP, Tier 2 ou un client transit à lui.",
"3h":"Le parcours d’architecte de la semaine",
"3h0":"Comment marche le Multimode",
"3h1":"Rejoindre",
"3h2":"Le Multimode fait entrer les réseaux d'autres gens dans ta partie. Chacun joue toujours sa propre partie sur son propre appareil : les serveurs ne font que passer des messages signés entre les parties. C'est par sauvegarde et entièrement facultatif.",
"3h3":"Masque un réseau et il disparaît de ta partie, pour toi seul. Signale-en un et les opérateurs de ton serveur y jettent un œil. Les opérateurs peuvent cacher un réseau sur leur serveur, et quand assez de serveurs votent pour l'exclure, il est exclu partout. Les votes ne sont pas publics : tu vois seulement qui est exclu et, si c'est toi, les raisons données. Ta propre partie continue toujours.",
"3h4":"Masquer, signaler, exclure",
"3h5":"Nouveaux et mentors",
"3h6":"Rien ne casse. Ta partie continue, ce que tu fais attend dans une file et part plus tard, et les accords en cours tiennent. Un réseau qui reste muet s'efface lentement : après une semaine son trafic part vers d'autres routes, après environ cinq semaines ses accords prennent fin avec un avis. Jamais de facture surprise.",
"3h7":"Les réseaux des autres joueurs sont des endroits que tes clients veulent atteindre. Fais du peering avec eux, aussi aux exchanges où ils sont inscrits, achète-leur du transit, des PNI, des ports d'exchange et des waves, échange de la capacité ou construisez ensemble un câble en consortium. Chaque réseau publie sa politique et ses prix, et les demandes qui les respectent peuvent être acceptées toutes seules, même quand l'autre joueur est absent. L'argent ne passe jamais d'une sauvegarde à l'autre : chaque partie compte son côté.",
"3h8":"Les accords sont privés",
"3h9":"Serveurs et opérateurs",
"3ha":"Les serveurs sont tenus par des joueurs, chacun par un ou plusieurs opérateurs, et tout le monde peut en lancer un. Certains se synchronisent avec d'autres serveurs, pour que tu croises des joueurs d'ailleurs. Le looking glass montre chaque serveur que ta partie connaît et comment il se synchronise. Tu peux en rejoindre quatre au plus.",
"3hb":"Active <b>Jouer avec d'autres</b> quand tu commences une nouvelle partie depuis l'écran titre, ou rejoins plus tard depuis Multimode dans le menu ou dans les Réglages. Les puzzles, les scénarios, le Sandbox et Open gates restent en solo. Le nom de ton réseau est public sur chaque serveur que tu rejoins, alors évite ton vrai nom.",
"3hc":"Quand un serveur tombe",
"3hd":"L'identité Multimode de ton réseau est une clé privée gardée dans cette sauvegarde. <b>Passer sur un autre appareil</b>, dans la fiche Multimode, télécharge le seul fichier qui la contient. Qui a ce fichier peut parler au nom de ton réseau : ne le partage jamais et ne le joins jamais à un rapport de bug. Les exports et les sauvegardes partagées ne contiennent jamais la clé.",
"3he":"Effacer",
"3hf":"Connectés seulement",
"3hg":"Chercher un réseau ou un numéro d'AS",
