"3lt":"Tous les POP",
"3lu":"Détails",
"3lv":"Fais glisser la barre de titre pour déplacer la fenêtre, et un bord ou un coin pour la redimensionner. Au clavier, les flèches la déplacent et Maj avec les flèches la redimensionne.",
