"3p0":"{n} mois",
"3p1":"{price} par an",
"3p2":"L'ingénierie optique est un département à part, et il n'est pas donné. Une équipe reprend le travail optique du stagiaire (optiques, systèmes de ligne, rendre des waves), monte d'une taille les waves louées qui chauffent, et planifie de nouvelles routes d'après ce que veulent les acheteurs du Lambda Bazaar : de la fibre creusée sur terre, votre propre câble sous la mer. Elle travaille avec un budget annuel, et de temps en temps elle se trompe.",
"3p3":"Des ingénieurs qui planifient et construisent vos routes en fibre et sous-marines, et s'occupent de vos optiques. Cher.",
