"3pv":"Le tracé de cette conception fait {km} km : trop long pour toute optique, même avec les deux améliorations. Une conception plus courte peut y arriver.",
"3pw":"Ce trajet est terrestre. Construis plutôt ta propre fibre.",
"3px":"Ton propre câble sous-marin demande le niveau clients {n}, ou Tier 1. Un courtier en câbles en pose dès le premier jour.",
"3py":"Ton câble sous-marin rien qu’à toi. Un navire le pose sur le fond marin, tu possèdes chacune de ses paires de fibres, et les longueurs d’onde de personne d’autre ne partagent ton verre. Ça coûte une somme franchement indécente et ça prend longtemps.",
"3pz":"Un jeu de navigateur gratuit et cartoon sur le fonctionnement d’Internet. Commence comme un minuscule réseau dans une seule ville, lance le haut débit grand public, achète du transit IP à des opérateurs Tier 1 et Tier 2, fais du peering sur des points d’échange, monte des interconnexions privées et des caches CDN embarqués, et pose de la fibre terrestre, des longueurs d’onde sous-marines et ta propre fibre noire avec du DWDM et des optiques ZR. Signe des clients entreprise, hébergement, trading haute fréquence, GPU pour l’IA et hyperscalers, et garde-les contents pendant que pelleteuses, requins, fat fingers, fuites de routes, attaques DDoS et géopolitique cassent tout.",
