"3qw":"<b>Le remote peering, c’est le dernier recours.</b> Les ports passent par un revendeur à 1,5× le prix, seuls 80 % du port sont vraiment à toi, la latence voyage sur le fabric, une seule panne du fabric fait tomber toutes les sessions, et beaucoup de réseaux sélectifs refusent les membres distants. Un POP ici, c’est mieux.",
