"48j":"Standards de POP",
"48k":"40 % de remise pendant 6 mois",
"48l":"<b>40 % de remise sur {ix} pendant 6 mois.</b><br>Ton account manager est soulagé. Lis les petites lignes plus tard.",
"48m":"<b>« Après consultation de la direction… »</b><br>Le prix a augmenté. La direction a été consultée.",
"48n":"Ensuite, le prix normal revient, plus de petits frais de gestion de fidélité.",
"48o":"<b>Extension commandée chez {net}.</b><br>{eta}.",
"48p":"<b>L'extension avec {net} est active :</b> {port}.",
"48q":"DE-KICKS Group · Customer Success",
"48r":"<b>Les commerciaux DE-KICKS sont encore en train de « s’aligner ».</b><br>Ils reviendront vers toi dans {n} jours.",
"48s":"<b>DE-KICKS va « revenir vers toi ».</b><br>Attends-toi à un mail intitulé « Petite question 🙂 » dans l’heure.",
"48t":"<b>Négociation en pause.</b><br>{why}",
"48u":"<b>« Juste pour cette fois. »</b><br>Ton account manager a trouvé une remise spéciale. N’en parle pas aux autres.",
"48v":"<b>Membre de LAG ajouté.</b><br>{net} à {city} est maintenant en {lag}.",
"48w":"<b>Membre de LAG retiré.</b>",
"48x":"<b>Le transit {net} est actif à {city}.</b><br>Full table reçue : ~1 000 000 de routes.",
"48y":"<b>Pas de transit dans ce scénario.</b><br>Uniquement peering, PNI, caches et ta propre fibre.",
"48z":"<b>{name} désactivé.</b><br>Il a fallu quatre clics, un sondage et une page « Nous sommes tristes de vous voir partir ».",
"49":"Deviens transit-free.",
"490":"<b>Port actif sur {ix} !</b><br>Maintenant, demande du peering ou rejoins le route server.",
"491":"<b>Port distant actif sur {ix}.</b><br>Il passe par un revendeur : attends-toi à une marge, un port surchargé et quelques réseaux qui refuseront de te parler. Ici, le route server est ton ami.",
"492":"<b>Session route server active.</b><br>Tu fais maintenant du peering avec tous les réseaux open de cet IX, d’un coup.",
"493":"<b>Routeur installé à {city}.</b><br>Le fournisseur l’a livré dans le bon sens, alors les techniciens du coin l’ont retourné. Ici, tout est à l’envers.",
"494":"<b>Routeur installé à {city}.</b><br>À l’envers, comme le veut la coutume ici. Les paquets n’ont pas l’air de s’en soucier.",
"495":"<b>Signé avec DE-KICKS.</b><br>Bienvenue dans la famille. Merci de ne dire à personne combien tu paies.",
"496":"Rester et prendre la remise",
"497":"<b>Ce PNI regroupe déjà {n} ports</b>, tout ce que tes routeurs ici peuvent tenir. Chaque routeur prend {more} membres d’un PNI, jusqu’à {max} : ajoute un routeur pour aller plus loin.",
"498":"Attends ! Avant de partir…",
"499":"Nous tenons trop à notre partenariat pour laisser un détail comme le prix se mettre en travers.",
"49a":"<b>Il te faut d’abord une licence.</b><br>Les réseaux étrangers ont besoin d’une joint-venture pour construire en Chine continentale.",
"49b":"Une fibre ici utilise des optiques que ce modèle n’accepte pas.",
"49c":"Un port ici est plus gros que {pn}.",
"49d":"Une longueur d’onde ici est plus rapide que {pn}.",
"49e":"<b>Aucun port routeur libre à {city}.</b><br>{u} sur {m} utilisés. Ajoute un routeur, ou passe à un modèle avec plus de ports (onglet Infra).",
"49f":"Tu utilises {u} ports ici et {r} × {model} n’en a que {max}.",
"49g":"Les adresses IP, un lieu plus précis qu'un pays, ton appareil, ton navigateur ou ton fuseau horaire. Un serveur n'utilise l'adresse de ta connexion qu'en mémoire, pour trouver le pays et freiner les déluges, et ne la note jamais. Les serveurs inscrits promettent que rien devant eux ne journalise les adresses non plus.",
"49h":"<b>Quitte</b> un serveur et ta partie cesse de lui parler ; ce qu'il gardait s'efface en 180 jours. <b>Partir pour de bon</b> signe un au revoir qui demande à chaque serveur d'effacer tout de suite les enregistrements de ton réseau (seul l'au revoir reste, 180 jours, pour se propager), et cette sauvegarde oublie son identité Multimode. Supprimer une sauvegarde l'enlève de cet appareil.",
"49i":"Partir",
"49j":"Pas de compte, pas d'e-mail, pas de cookies. Voici tout ce que le jeu stocke et tout ce qui quitte ton appareil.",
"49k":"Sur seriesoftub.es, la page charge un petit compteur de visites (depuis jsDelivr, qui rapporte à stats.seriesoftub.es). Il compte une visite avec l'adresse de la page, la page d'où tu viens et la largeur de la fenêtre, combien de temps la page est restée ouverte, et les noms de certains moments du jeu, comme commencer une partie ou gagner un badge. Il ne pose aucun cookie et ne stocke rien dans ton navigateur. Le compteur est ridiculytics, conçu par l'auteur du jeu et hébergé sur notre propre serveur : pas de base de données, rien d'écrit sur disque, seulement des compteurs en mémoire (par page, site d'origine sous forme de nom d'hôte, pays, navigateur, système d'exploitation, type d'appareil, classe de taille d'écran et moment du jeu). Ton adresse IP ne sert que pendant le comptage de ta visite, pour trouver le pays, et n'est jamais stockée ni journalisée ; les visiteurs uniques sont comptés avec un hachage dont le secret change toutes les 24 heures, donc les visites ne peuvent pas être reliées d'un jour à l'autre. Les copies du jeu ailleurs n'envoient rien.",
"49l":"Sur cet appareil",
"49m":"Cette page sur le web",
"49n":"Le compteur de visites",
"49o":"Les chiffres de trafic 72 heures (et tes plus récents), les accords 30 jours, et la description de ton réseau jusqu'à 180 jours de silence. Les heures sont arrondies à cinq minutes. Les votes des opérateurs sur un réseau durent 97 jours.",
"49p":"Ce que gardent les serveurs",
"49q":"Ce que les serveurs ne gardent jamais",
"49r":"Ce que le jeu garde",
"49s":"Ce que le jeu garde et envoie",
"49t":"Quand tu rejoins un serveur",
"49u":"Pendant que tu joues",
"49v":"Tes chiffres actuels (les mêmes que ci-dessus, rien de plus) toutes les 10 secondes tant que le jeu est ouvert et qu'ils ont changé, pour que les classements montrent ce qui se passe maintenant. Les serveurs les gardent seulement en mémoire, jamais sur disque, et les oublient 15 minutes après les derniers.",
"49w":"Ta partie envoie ces enregistrements signés : le nom, le numéro d'AS et le marché d'origine de ton réseau dans le jeu, le jour de jeu et le jour réel où il a rejoint, ses villes avec POP et exchange, le nombre de clients, les chiffres et le mix de trafic, combien de trafic il échange avec le réseau de chaque autre joueur, s'il est Tier 1 ou Tier 2, sa politique et ses prix publiés, à qui il achète ou vend du transit (jamais le prix), et le modèle et le harness d'IA quand un agent IA le joue. Les accords partent scellés pour l'autre joueur seulement. Un signalement que tu envoies sur un autre réseau (lequel, et pourquoi) va aux opérateurs de ce serveur. Ton vrai pays est ajouté tant que <b>Partager mon pays</b> est activé, et il l'est jusqu'à ce que tu le désactives.",
"49x":"Tes sauvegardes, réglages, badges et progrès restent dans le stockage de ce navigateur. En Multimode s'ajoutent la clé privée de ton réseau (dans la sauvegarde), ce que tes serveurs ont envoyé sur les autres réseaux (oublié après 180 jours sans nouvelles) et une clé d'opérateur si tu en as importé une. Rien n'est envoyé tant que tu ne rejoins pas de serveur ou n'envoies pas toi-même une sauvegarde.",
"49y":"1.6T sur chaque saut de Los Angeles à Sydney",
"49z":"1.6T sur chaque saut de Miami à Madrid",
