"4ge":"Un IX associatif dans un sous-sol de Hudson Street. Cream cheese non compris.",
"4gf":"Un IX associatif géré depuis l’étage d’un bar à cidre. Minuscule, pas cher, et chaque membre a droit à un verre.",
"4gg":"Un IX commercial plus petit, au bout de la rue de DE-KICKS. Publie ses prix sur une seule page web, ce que DE-KICKS considère comme un acte de guerre. Les ports sont livrés sans webinaire commercial.",
"4gh":"Dense, bourratif et vraiment pas cher.",
"4gi":"Chaque session inclut une pause café. Strictement obligatoire.",
"4gj":"Des ports grillés, servis avec moutarde et bière fraîche.",
"4gk":"Cultivé en laboratoire par l'opérateur historique. Sa famille y est ; les autres paient pour regarder.",
"4gl":"Tout en couches, résilient et toujours ouvert, on ne sait trop comment.",
"4gm":"Plein de petites sessions servies dans de petits paniers vapeur.",
"4gn":"Détenu par ses membres et à but non lucratif. Plus petit que LYNX, mais il y a des biscuits à l’AG.",
"4go":"L’IX street food de Mumbai. Rapide, épicé et pas cher.",
"4gp":"Un seul fabric pour tout le pays. Distribué, pas cher, et un peu content de lui.",
"4gq":"Façon tartine, pas cher et dispo à 3 h du matin.",
"4gr":"Ouvre à 18 h, amuse-bouches offerts, ferme quand la dernière session tombe.",
"4gs":"Géré par des hackers sous caféine. Le route server a une boule à facettes.",
"4gt":"Peering settlement-free aux racines frisonnes. Les ports 10G et 100G ne coûtent rien. Apporte un ASN et de l’appétit pour les route servers. La mayonnaise est en supplément.",
"4gu":"Né dans le garage de quelqu’un, comme tout le reste par ici.",
"4gv":"Fort, sucré et moins cher que l’opérateur historique.",
"4gw":"Prend une éternité à mettre en place, mais très copieux.",
"4gx":"Le challenger. Frais chaque matin, un peu rassis le soir.",
"4gy":"Le challenger d’IX Straya. Surgit au bord de chaque ville, y compris celles dont personne d’autre ne s’occupe. Un goût qui s’acquiert, comme la Vegemite.",
"4gz":"Le challenger du fabric DE-KICKS, roulé et prêt à emporter.",
"4h":"Aie des ports sur 10 points d’échange.",
"4h0":"L’IX historique de Madrid. Interconnexion neutre, saveur locale et un route server qui ne fait jamais la sieste.",
"4h1":"Le plus ancien IX de Johannesburg, géré par l’association locale des FAI. Touche du bois avant chaque fenêtre de maintenance.",
"4h2":"Tout le quartier porte la maison ensemble. Gratuit, avec la bénédiction du gouvernement.",
"4h3":"Tokyo compte plus d’IX qu’on ne peut en nommer. Celui-ci a été fondé par un géant du haut débit et arrive soigneusement emballé, chaque membre dans son compartiment.",
"4h4":"Warsaw compte plus d’IX qu’on ne peut en compter. Celui-ci est le deuxième plus grand, cette semaine.",
"4h5":"Tu ne vois pas le fabric, mais il est bien là.",
