"4kf":"Suis un paquet saut par saut et vois pourquoi il sort là où il sort.",
"4kg":"Tracer",
"4kh":"Quand Auto-TE fonctionne, les circuits L2 peuvent se répartir sur plusieurs chemins selon tes règles de débordement. Les chemins épinglés restent fixes.",
"4ki":"<b>Réduis d’abord un PNI.</b><br>Ton PNI avec {net} regroupe {n} ports, et avec un routeur de moins il n’en tient que {m}.",
