"4lf":"Un petit réseau, un objectif retors.",
"4lg":"Casse-tête",
"4lh":"Pannes rares, pas de DDoS, pas de singe du chaos, pas de conférences. Les PNI sont actifs dès la commande, les coupures sous-marines se réparent sans navire câblier, les chantiers prennent des jours, les prix ne bougent pas. Clients patients, notifications discrètes et un prêt de sauvetage au lieu de la fin de partie.",
"4li":"De vrais délais, de vraies pannes, un vrai marché. Le jeu classique.",
