"4mz":"<b>Votre partie n'est pas sauvegardée.</b> Ce navigateur n'autorise pas le jeu à stocker quoi que ce soit (fenêtre privée ou données de sites désactivées). Exportez une sauvegarde pour garder votre réseau.",
"4n":"Aie des contrats sur 3 campus IA différents en même temps.",
"4n0":"Ce fichier contient l'identité Multimode du réseau. Il jouait sur {servers}. Il arrive hors ligne : une fois chargé, rejoins ces serveurs depuis Multimode, et seulement si tu les connais.",
"4n1":"<b>Votre partie n'est pas sauvegardée.</b> Votre réseau est devenu trop gros pour le stockage de ce navigateur. Exportez une sauvegarde maintenant et gardez le fichier : c'est votre copie de secours.",
"4n2":"<b>Objectif :</b> {goal} · <b>Durée :</b> {d} jours · départ à {city}",
