"4n5":"{name} : réussi en {d} jours",
"4n6":"Pic de trafic servi en un an. Ton record cette semaine : {best}.",
"4n7":"Pic de trafic servi en un an.",
"4n8":"Pic de trafic servi en un an. Nouveau record perso cette semaine !",
