"4na":"Partager mon résultat",
"4nb":"Départ à {city} · {mods} · un an, score = pic de trafic. Le même monde pour tout le monde cette semaine.",
"4nc":"Avec de la marge.",
"4nd":"Ton record : {best}.",
"4ne":"Ton score : {score}",
"4nf":"1.6T sur chaque saut de Miami à Madrid et de Lisbonne à Lagos, et 100 Gbps servis",
"4ng":"90 jours d’affilée avec 99,5 % de la demande servie",
"4nh":"99 % de couverture et 150 Gbps servis",
"4ni":"Un chemin du Cap au Caire, avec Lagos et Nairobi aussi sur votre réseau, et 150 Gbps servis",
"4nj":"Un chemin de Los Angeles à Sydney en 1.6T sur chaque saut, un chemin de Los Angeles à Tokyo, et 150 Gbps servis",
"4nk":"Un chemin de Marseille à Singapour, et 80 Gbps entre l’Asie et le reste de ton réseau pendant 30 jours d’affilée",
"4nl":"Amsterdam, capitale européenne de l’hébergement, en pleine saison des botnets. Chaque grille-pain connecté, babyphone et frigo jamais patché de la planète a choisi son camp, et ce n’est pas le tien. Une vague tous les quelques jours, de plus en plus souvent dans les térabits, pendant que tout le reste continue de casser aussi. Tu commences avec du matériel plus gros déjà débloqué, et tu en auras besoin.",
"4nm":"Internet à domicile à Sydney, Melbourne, Brisbane, Adélaïde et Perth, deux câbles différents vers l’étranger, et 500 Gbps servis",
"4nn":"Du Cap au Caire",
"4no":"Le Cap. Construis un réseau à travers l’Afrique : chaque frontière veut son propre permis, et les groupes électrogènes font partie du réseau.",
"4np":"Cogentle et Goggle ne se parlent plus, et cette fois c’est définitif. Achète le transit pas cher, si tu l’oses.",
"4nq":"Bogotá, Lima, Santiago et São Paulo reliées à Panama, et 150 Gbps servis",
"4nr":"Assurer tout le Carnaval",
"4ns":"Tous les câbles de la mer Rouge sont coupés, tout comme le saut vers l’Égypte. Fais quand même parler Marseille et Singapore : par le tour de l’Afrique, par voie terrestre, ou par l’autre côté de la planète.",
"4nt":"Tous les IX sont gérés par DE-KICKS",
"4nu":"Les eyeballs croissent 50 % plus vite",
"4nv":"La fibre au sous-sol",
"4nw":"Peering Gangnam Style",
"4nx":"Tiens 20 flots, dont 5 au-dessus de 1 Tbps : chaque cible à 97 % ou mieux, personne d’autre touché",
"4ny":"Honolulu, au milieu du Pacifique. Les câbles entre les Amériques, l’Asie et l’Australie sont si longs qu’une longueur d’onde n’y transporte que 400G ou 800G. Arrête la lumière sur une île, fais-la repartir à neuf, et chaque saut devient plus court et plus rapide. Tu commences avec le matériel 1.6T débloqué.",
"4nz":"Accent mi-atlantique",
"4o":"J’ai survécu à l’éléphant",
"4o0":"Que du Spätzle-IX",
"4o1":"Ordre et progrès",
"4o2":"Ponta Delgada, aux Açores, à mi-chemin de l’Atlantique. De la Floride à l’Espagne, c’est juste trop long pour une onde de 1.6T : en ligne droite, elle transporte 1.2T. Atterrissez sur les îles entre les deux, relancez la lumière, et chaque saut passe à 1.6T ou mieux. De Lisbonne à Lagos, le 1.6T passe d’une traite, mais cher : les Canaries coûtent moins. Vous commencez avec l’équipement 1.6T débloqué.",
"4o3":"Des ports sur 15 IX.brrr que votre backbone relie à São Paulo, dont un à Manaus, et 200 Gbps servis",
"4o4":"Couvre 50 % d’internet et sers 300 Gbps",
"4o5":"Crise en mer Rouge",
"4o6":"Rio en partant de zéro. Le Carnaval commence dans 90 jours et veut 400 Gbps pendant cinq jours d’affilée. Le monde entier regarde.",
"4o7":"<b>Mode bac à sable</b><br>Un milliard de dollars et tout débloqué. Chaos : {chaos}. Construis l’internet dont tu as toujours rêvé, et garde une pelleteuse de rechange sous la main.",
"4o8":"<b>Mode bac à sable</b><br>Un milliard de dollars, tout débloqué, et rien ne casse jamais. Construis l’Internet dont tu as toujours rêvé.",
"4o9":"São Paulo. Le Brésil est un continent : quarante IX.brrr, des milliers de provedores, et l’Amazonie entre toi et le nord.",
"4oa":"Séoul, où l’expéditeur paie. Chaque Gbps qu’un opérateur livre en Corée te coûte une taxe « l’expéditeur paie » en plus de la facture de transit, les trois opérateurs historiques ne parlent que par un PNI payant, le gigabit à la maison se vend au prix d’un bibimbap et les utilisateurs coréens remarquent chaque milliseconde. Le transit à Tokyo est bon marché, si tes clients supportent le voyage.",
"4ob":"{g} Gbps servis, Séoul bien servie ({q} %), 99 % de portée et un bénéfice mensuel",
"4oc":"Saison des requins : coupures sous-marines deux fois plus probables",
"4od":"Démarre à Panama City. Rien ne traverse le bouchon du Darién par voie terrestre, et les Andes barrent la route à tout le reste.",
"4oe":"Démarre à Stuttgart, où personne ne vend de transit. Atteins Internet uniquement via peering, PNI, caches et ta propre fibre. Aucun transit, nulle part, jamais.",
"4of":"Démarre avec seulement $100k",
"4og":"Sydney, 2013. Le Toilet Paper Group a tiré sa propre fibre jusqu’au sous-sol des immeubles, et le réseau national a crié à l’écrémage. À toi : passe outre le Nearly Broadband Network, paie la taxe et arrive le premier.",
"4oh":"Tallinn, où personne ne vend de transit : votre internet est de l’autre côté de l’eau. Les navires traînent leurs ancres sur les câbles de la Baltique trois fois plus souvent que d’habitude.",
