"4ql":"{n} ports",
"4qm":"aucun chemin pour l’instant",
"4qn":"<b>{p} du trafic de {city} vient de {to} : {ms} ms aller-retour.</b> Les utilisateurs coréens remarquent tout ce qui dépasse 8 ms, et au-delà de 40 ms le haut débit compte comme un mauvais service. Sers davantage depuis Séoul : peering, caches et PNI ici, ou du transit local si tu supportes la taxe « l’expéditeur paie ».",
"4qo":"<b>{p} du trafic de {city} est ramené vers le transit à {to} : {ms} ms aller-retour.</b> Les utilisateurs le sentent au-delà de 20 ms (environ 1 500 km), et au-delà de 50 ms le haut débit et les services internet comptent comme un mauvais service. Achetez du transit ici ou à proximité, ou peerez localement.",
