"conferences.the_hallway_track_moved_to_a":"Le hallway track a migré vers un bar du port, où la femme derrière le comptoir a continué à servir de l’aquavit bien après minuit sans demander à personne son AS path. De retour au bar de l’hôtel, quelqu’un a dit « allez, un dernier verre ». Tes sessions BGP ont tenu toute la nuit. Toi aussi.",
