"ez":"De l’Afrique de l’Est jusqu’à l’Europe par la mer Rouge. Simple comme bonjour.",
"f":"<b>Tu n’as pas de POP à {city}.</b><br>Construis-en d’abord un là-bas, puis fonde l’IX.",
"f0":"De la fibre le long de la côte de la Colombie-Britannique, vers des villages qui n’avaient que le satellite.",
"f1":"Des Fidji aux Samoa. Toujours de la place pour un paquet de plus.",
"f2":"Des Fidji aux Tonga, la seule voie d’accès. Essaie de le dire trois fois très vite.",
"f3":"De la Floride au Brésil en descendant l’arc des îles, depuis l’an 2000, et ça se voit.",
"f4":"De la Floride à la Jamaïque et à la Colombie, sur la même route une seconde fois.",
"f5":"De la Floride au nord de l’Espagne via les Bermudes et les Açores. Il traverse le Triangle tout droit et en est toujours ressorti. Jusqu’ici.",
"f6":"De la Floride au Brésil en faisant le tour des Caraïbes, le câble perso du grand opérateur téléphonique.",
"f7":"De l’île de Vancouver droit vers le Japon, le premier nouveau câble sur la côte pacifique du Canada depuis des décennies.",
"f8":"De Fujairah à Mumbai, autour de la pointe de l’Inde jusqu’à Chennai, puis jusqu’à Singapore.",
"f9":"De Gênes à la Sicile puis jusqu’à Athens, posé par un géant de la recherche en ligne lassé de louer.",
"fa":"De l’Allemagne à Bornholm et Copenhague, puis le long de la côte suédoise jusqu’à Stockholm. Si les ancres le veulent bien.",
"failures.a_b_is_down_same_cable":"{a}–{b} est en panne. Même câble, nouvelle ancre. L’équipe de réparation a créé une carte de fidélité.",
"failures.a_backhoe_found_your_fiber_between":"Un tractopelle a trouvé ta fibre entre {a} et {b}.",
"failures.a_backhoe_putting_in_a_new":"Une pelleteuse qui préparait une nouvelle station-service a creusé en plein dans ta fibre {a}–{b}. D’après les plans, elle était deux mètres plus à gauche.",
"failures.a_beaver_chewed_through_your_a":"Un castor a rongé ta longueur d’onde {a}–{b}. Il s’est servi de la fibre pour finir un barrage.",
"failures.a_botnet_of_40_000_smart":"un botnet de 40 000 grille-pain connectés",
"failures.a_botnet_run_from_a_cloud":"un botnet qui tourne dans un cloud que tu héberges aussi",
"failures.a_cargo_ship_forgot_to_raise":"Un cargo a « oublié » de remonter son ancre et l’a traînée sur ton câble {a}–{b}. Les armateurs sont désolés, et assez difficiles à joindre.",
"failures.a_crocodile_took_a_bite_out":"Un crocodile a croqué un morceau de ta fibre {a}–{b}. Il n’a pas trouvé ça terrible.",
"failures.a_crypto_bro_shorting_your_stock":"un crypto-bro qui shorte ton action",
"failures.a_curious_shark_bit_your_subsea":"Un requin curieux a mordu ton câble sous-marin {a}–{b}.",
"failures.a_digger_found_your_a_b":"Une pelleteuse a trouvé ta fibre {a}–{b}. Une autre pelleteuse arrive pour la réparer.",
"failures.a_dirty_connector_on_a_b":"Un connecteur sale sur {a}–{b} perd 2 % des paquets. TCP déteste ça : le débit s’effondre alors que le lien a l’air nickel.",
"failures.a_drop_bear_fell_on_the":"Un drop bear est tombé sur l’équipe d’épissure sur {a}–{b}. Ils refusent de travailler sous les arbres, et la coupure est sous les arbres.",
"failures.a_farmer_s_post_hole_digger":"La tarière à piquets d’un éleveur a trouvé ta fibre {a}–{b}. Les moutons regardaient.",
"failures.a_ferry_dropped_anchor_in_cook":"Un ferry a jeté l’ancre dans le détroit de Cook et a trouvé ton câble {a}–{b}. Le ferry va bien.",
"failures.a_fishing_boat_with_an_unusually":"Un bateau de pêche à l’ancre étonnamment lourde a coupé {a}–{b}. Pêche du jour : un câble.",
"failures.a_fridge_that_achieved_sentience_and":"un frigo devenu conscient qui a choisi la violence",
"failures.a_gaming_clan_that_lost_one":"un clan de gamers qui a perdu un match",
"failures.a_great_white_took_an_interest":"Un grand requin blanc s’est intéressé à ton câble {a}–{b} et l’a mordu. Puis il l’a recraché : pas assez de goût.",
"failures.a_kangaroo_boxed_your_field_tech":"Un kangourou a boxé ton technicien sur {a}–{b}. Le technicien a perdu aux points, et l’épissure attendra.",
"failures.a_kangaroo_hit_the_fiber_hut":"Un kangourou a percuté la cabane fibre sur {a}–{b}. La cabane a perdu.",
"failures.a_kea_pulled_the_rubber_seals":"Un kéa a arraché les joints en caoutchouc du boîtier d’épissure sur {a}–{b}, puis s’est attaqué à la camionnette. Les kéas sont comme ça.",
"failures.a_kilometre_of_copper_went_missing":"Un kilomètre de « cuivre » a disparu de ta tranchée {a}–{b}. C’était ta fibre. Le ferrailleur l’a renvoyée avec un petit mot.",
"failures.a_landslide_in_the_andes_buried":"Un glissement de terrain dans les Andes a enseveli ta fibre {a}–{b}.",
"failures.a_llama_herd_trampled_the_fiber":"Un troupeau de lamas a piétiné la balise de fibre sur {a}–{b}. Puis un tractopelle a trouvé la fibre.",
"failures.a_pppoe_hop_shaved_8_bytes":"Un saut PPPoE a rogné 8 octets sur ta MTU et personne n’a prévenu les serveurs. Les gros transferts vers {net} restent bloqués pour toujours ; les petits marchent très bien, ce qui rend le tout bien pire.",
"failures.a_printer_just_one_printer_nobody":"une imprimante. Une seule imprimante. Personne ne sait comment",
