"failures.a_sulphur_crested_cockatoo_chewed":"Un cacatoès à huppe jaune a rongé ta fibre {a}–{b}, puis il est revenu pour celle de secours.",
"failures.a_teenager_with_a_stolen_credit":"un ado avec une carte bancaire volée et une rancune",
"failures.a_trawler_off_ostend_dragged_its":"Un chalutier au large d’Ostende a traîné son chalut en plein sur ton câble {a}–{b}. La mer du Nord fait une trentaine de mètres de fond et grouille de bateaux.",
"failures.a_wind_farm_service_vessel_dropped":"Un navire de maintenance d’un parc éolien a jeté l’ancre sur ton câble {a}–{b}. Il était là pour réparer une éolienne.",
"failures.an_earthquake_shook_your_a_b":"Un séisme a déboîté ta fibre {a}–{b} quelque part au-dessus de 4 000 mètres.",
"failures.an_eastern_brown_snake_moved_into":"Un serpent brun de l’Est s’est installé dans la chambre de tirage sur {a}–{b}. Personne ne se porte volontaire pour réparer ta fibre.",
"failures.an_undersea_landslide_snapped_a_b":"Un glissement de terrain sous-marin a sectionné {a}–{b}.",
"failures.an_undersea_volcano_erupted_next_to":"Un volcan sous-marin est entré en éruption à côté de ton câble {a}–{b}. Le navire de réparation l’a retrouvé en morceaux, certains à des kilomètres.",
"failures.another_anchor_another_cut_your_a":"Encore une ancre, encore une coupure : ton câble {a}–{b}. Le navire de réparation connaît le chemin, maintenant.",
"failures.another_of_vietnam_s_subsea_cables":"Encore un câble sous-marin du Vietnam cassé : ton lien {a}–{b}. Le navire de réparation viendra après les fêtes. Lesquelles, mystère.",
"failures.box_jellyfish_season_at_the_a":"Saison des cuboméduses à l’atterrissement {a}–{b}. Les plongeurs ont jeté un œil et sont remontés sur le bateau.",
"failures.bushfire_season_the_fiber_along_a":"Saison des feux de brousse : la fibre le long de {a}–{b} a fondu dans son fourreau. Les pompiers ont sauvé la ville, pas le fourreau.",
"failures.crc_errors_on_a_b_a":"Erreurs CRC sur {a}–{b} : une optique limite abîme quelques trames sur mille.",
"failures.every_unpatched_baby_monitor_in":"tous les babyphones non patchés d’Europe",
"failures.frost_heave_cracked_the_duct_on":"Le gel a fissuré le fourreau sur {a}–{b}, et un castor a fait le reste.",
"failures.hash_polarisation_on_your_lab_nearly":"Polarisation du hash sur ton {lab} : presque tous les flux tombent sur le même membre. Le bundle se dit up. Il est aussi plein.",
"failures.lacp_fast_slow_timer_mismatch_on":"Timers LACP fast/slow incohérents sur ton {lab} : un membre n’arrête pas de sortir du bundle sur timeout et d’y revenir.",
"failures.magpie_swooping_season_the_field":"Saison des attaques de pies : les techniciens sur {a}–{b} refusent de sortir de la camionnette, et ta coupure reste coupée.",
"failures.microbursts_on_a_b_overflow_shallow":"Les microbursts sur {a}–{b} débordent les buffers peu profonds des routeurs : 0,5 % de perte en pointe, et chaque visio le remarque.",
"failures.one_member_of_your_lab_was":"Un membre de ton {lab} a été brassé sur le mauvais switch. LACP le garde suspendu, à juste titre.",
"failures.road_widening_near_a_cut_your":"Un élargissement de route près de {a} a coupé ta fibre vers {b}. C’est toujours un élargissement de route.",
"failures.road_works_cut_a_b_nobody":"Des travaux de voirie ont coupé {a}–{b}. Personne n’a fait de DICT avant de creuser.",
"failures.snow_closed_the_mountain_pass_and":"La neige a fermé le col, et l’équipe de réparation avec : {a}–{b} est tombé.",
"failures.somebody_who_did_not_like_your":"quelqu’un qui n’aimait pas le nom de ton réseau",
"failures.someone_filtered_all_icmp_on_your":"Quelqu’un a filtré tout l’ICMP sur ton edge « pour la sécurité ». Le Path MTU Discovery est cassé, et les connexions vers {net} se figent juste après le handshake.",
"failures.someone_set_min_links_on_your":"Quelqu’un a réglé min-links sur ton {lab} au nombre de membres. Un membre a flappé, donc tout le bundle est tombé.",
"failures.squirrels_chewed_through_a_b_they":"Des écureuils ont rongé {a}–{b}. Non, rien de rien, ils ne regrettent rien.",
"failures.ten_thousand_smart_light_bulbs":"dix mille ampoules connectées qui clignotent à l’unisson",
"failures.termites_ate_the_duct_on_a":"Les termites ont mangé le fourreau sur {a}–{b}. Puis la fibre. Puis le fourreau de remplacement.",
"failures.the_emus_won_again_a_mob":"Les émeus ont encore gagné : une bande a couché les bornes de repérage sur {a}–{b}, et une niveleuse a creusé en plein dans la fibre.",
"failures.the_internet_connected_kettles_of_a":"les bouilloires connectées d’un pays entier",
"failures.the_monsoon_flooded_a_manhole_on":"La mousson a inondé une chambre de tirage sur {a}–{b}. La fibre est maintenant sous l’eau, tout comme la chambre.",
"failures.the_repair_ship_s_compass_spun":"La boussole du navire de réparation a tourné en rond au-dessus de votre câble {a}–{b}. Il est coupé, et personne n’est d’accord sur l’endroit.",
"failures.the_sandflies_drove_your_splicing":"Les mouches des sables ont chassé ton équipe d’épissure de {a}–{b}. Elle reviendra quand le vent se lèvera.",
"failures.the_seabed_off_tonga_slid_down":"Le fond marin au large des Tonga a glissé le long d’une pente et a emporté ton câble {a}–{b}. Le navire de réparation arrive de Papouasie-Nouvelle-Guinée.",
"failures.the_wet_season_washed_out_the":"La saison des pluies a emporté la piste vers ta fibre {a}–{b}. L'équipe y sera quand l'eau aura baissé.",
"failures.thieves_dug_up_your_a_b":"Des voleurs ont déterré ton câble {a}–{b}, persuadés que c’était du cuivre. C’était de la fibre. Ils l’ont laissé coupé dans le fossé, profondément déçus.",
"failures.your_a_b_cable_broke_in":"Ton câble {a}–{b} a cassé au même endroit que la dernière fois. L’équipe de réparation l’a reconnu.",
"failures.your_a_b_cable_is_cut":"Ton câble {a}–{b} est encore coupé. Le navire câblier ne repart même plus vraiment : il se gare juste au-dessus.",
"failures.your_a_b_cable_went_quiet":"Votre câble {a}–{b} s’est tu quelque part dans le Triangle des Bermudes. Le navire de réparation est parti le chercher, et lui non plus n’a pas encore rappelé.",
"failures.your_a_b_fiber_broke_somewhere":"Ta fibre {a}–{b} a cassé quelque part dans le Nullarbor. L’équipe de soudure a fait ses valises pour une semaine.",
"failures.your_a_b_fiber_is_down":"Ta fibre {a}–{b} est coupée. L’équipe de réparation a trouvé des traces de dents, une hutte et un castor très fier.",
"failures.your_scrubbing_center_returns_clean":"Ton centre de scrubbing renvoie le trafic propre dans un tunnel GRE, et personne n’a clampé le MSS. Les gros paquets vers {net} disparaissent, donc les pages chargent à moitié puis s’arrêtent.",
"fb":"La côte ouest du Groenland, ville par ville : de Nuuk à Sisimiut puis Aasiaat, sous les icebergs.",
"fc":"De Guam aux Îles Marshall, avec une escale à chaque atoll qui envoie une lettre.",
"fd":"Du Guyana directement à la Barbade, sans passer par Trinidad, pour une fois.",
"fe":"D’Haïti à la Jamaïque par le passage du Vent : une seule nouille entre deux voisins.",
