"hyper_az.hit_cert":"Un certificat de {zone}, à {city}, a expiré à 3 h du matin et a emporté ce bâtiment avec lui. Les autres zones ont répondu à sa place. La région sert {p}.",
"hyper_az.hit_cooling":"Le refroidissement de {zone}, à {city}, a lâché. Ce bâtiment s'est éteint tout seul ; les autres ont pris sa charge. La région sert {p}.",
"hyper_az.hit_squirrel":"Un écureuil a court-circuité le tableau électrique de {zone}, à {city}. Ce bâtiment est dans le noir ; les autres n'ont pas cillé. La région sert {p}. L'écureuil va bien.",
"hyper_az.hit_ups":"La salle des batteries de {zone}, à {city}, a raté son test mensuel en tombant vraiment en panne. Un bâtiment a redémarré, lentement ; le reste a continué à {p}.",
