"hyper_colo.t_cage":"Cage louée",
"hyper_dir.intro_ai":"🧠 <b>Les labos d'IA ont ton numéro.</b> Ils veulent des semaines d'entraînement entre deux de tes régions. Des millions si c'est à l'heure, la moitié en retard.",
"hyper_dir.intro_ddos":"🧨 <b>Les botnets ont trouvé ton adresse.</b> De temps en temps, quelqu'un inonde un locataire. Des ports en réserve et un backbone large encaissent.",
"hyper_dir.intro_fail":"🦍 <b>Deux régions, donc une région entière peut tomber.</b> Ses utilisateurs basculent sur sa réplique. Garde le retard bas et le backbone large : c'est l'examen.",
"hyper_dir.intro_freeze":"🎮 <b>Ton studio de jeux prépare une sortie.</b> Les jours de lancement multiplient son trafic et gèlent ton réseau : construis avant le gel.",
"hyper_dir.intro_inc":"☁️ <b>Tu es assez grand pour tomber en panne façon cloud.</b> Certificats expirés, tempêtes de réplication, Route 66 qui perd un point. Chaque panne arrive avec son bouton de réparation.",
"hyper_dir.intro_law":"🏛️ <b>Les régulateurs ont découvert les clouds.</b> Les lois arrivent avec un préavis : construis où ils le demandent, ou paie.",
"hyper_dir.intro_pev":"⚡ <b>L'électricité a ses humeurs, maintenant.</b> Canicules et crises de l'énergie frappent des continents entiers : les factures grimpent et les refroidisseurs transpirent. Si un réseau va disjoncter, tu es prévenu un jour avant.",
"hyper_dir.intro_rv":"🥊 <b>Les clouds rivaux t'ont remarqué.</b> Ils feront des offres à tes locataires, dragueront les mécontents au renouvellement et lanceront parfois une guerre des prix.",
"hyper_dir.u_ai":"des labos d'IA en quête d'entraînements",
"hyper_dir.u_ddos":"botnets",
"hyper_dir.u_fail":"pannes de régions entières (dès que tu en as deux)",
"hyper_dir.u_freeze":"les jours de sortie de tes studios de jeux",
"hyper_dir.u_inc":"pannes à l'échelle du cloud",
"hyper_dir.u_law":"régulateurs",
"hyper_dir.u_pev":"canicules et crises de l'énergie",
"hyper_dir.u_rv":"clouds rivaux",
"hyper_fail.msg_cert":"Un certificat a expiré à {city} à 3 h du matin et a emporté toute la région. Le rappel est parti dans une boîte que personne ne lit.",
"hyper_fail.msg_cooling":"Le refroidissement de {city} a lâché en pleine canicule. Les serveurs se sont éteints avant de finir en barbecue.",
"hyper_fail.msg_dns":"Quelqu'un a poussé un changement DNS sur tous les racks de {city} d'un coup. C'était le DNS. C'est toujours le DNS.",
"hyper_fail.msg_squirrel":"Un écureuil a court-circuité le poste principal de {city}. Toute la région est dans le noir. L'écureuil va bien.",
"hyper_fail.msg_tag":"Un stagiaire a étiqueté la région de {city} « temporaire » et le script de nettoyage l'a pris au pied de la lettre.",
"hyper_fail.msg_ups":"La salle des batteries de {city} a raté son test mensuel en tombant vraiment en panne. Toute la région a redémarré, lentement.",
"hyper_fail.news_cats":"FLASH : des millions de photos de chats perdues dans la panne de la région cloud de {city}",
"hyper_fail.news_save":"À LA UNE : des joueurs perdent des sauvegardes de 400 heures dans l'effondrement de la région de {city}",
