"hyper_freeze.fail_lag":"{game} est sorti avec 900 ms de lag. Les speedrunners font maintenant du speed-walking. {name} ne rit pas.",
"hyper_freeze.fail_meme":"Le lancement de {game} a planté si fort qu'il est devenu un mème avant de devenir un jeu. {name} « réexamine ses partenaires ».",
"hyper_freeze.fail_queue":"Le lancement de {game} par {name} : quatre millions de joueurs dans la file de connexion, trois sont entrés. Les critiques parlent d'un « simulateur de salle d'attente ».",
"hyper_freeze.fail_refund":"Les demandes de remboursement de {game} dépassent le nombre de joueurs. Le PDG de {name} a publié ta page d'état.",
"hyper_inc.cert_cal":"Le rappel pour renouveler le certificat de la porte d'entrée à {city} était dans l'agenda de quelqu'un parti en 2023. Les utilisateurs voient un avertissement rouge et vont ailleurs.",
"hyper_inc.cert_exp":"Le certificat TLS de ta porte d'entrée à {city} a expiré à minuit. Les navigateurs affichent une page rouge effrayante ; les utilisateurs font le tour vers une autre porte, s'il y en a une.",
"hyper_inc.dns_ttl":"Quelqu'un a mis tous les TTL de Route 66 à zéro « pour que les changements passent plus vite ». Les serveurs de noms ont fondu ; {n} locataires avec DNS sont plus ou moins hors ligne.",
"hyper_inc.dns_zone":"Route 66 est en panne : un fichier de zone a perdu son point final. {n} locataires avec DNS appellent en même temps. C'était le DNS. C'est toujours le DNS.",
"hyper_inc.melt_queue":"{game} est sorti et la file d'attente de connexion de {name} a atteint la Lune. La région de {city} est en feu et sert moins jusqu'à la fin du lancement.",
"hyper_inc.melt_retry":"Tous les joueurs de {game} ont cliqué sur réessayer en même temps. La tempête de tentatives a emporté la région de {city} ; {name} accuse le cloud, toi le bouton.",
"hyper_inc.pow_crane":"Une grue du chantier voisin a rencontré le poste électrique qui alimente {city}. {util} s'en occupe ; d'ici là, la région sert moitié moins.",
"hyper_inc.pow_diesel":"{util} a perdu un transformateur à {city}. Les groupes électrogènes ont démarré, puis sont tombés à sec : le budget diesel est parti dans la fête de fin d'année.",
"hyper_inc.pow_kite":"Une fête du cerf-volant s'est emmêlée dans les lignes électriques vers {city}. {util} dit que c'était un très joli cerf-volant. La région sert moitié moins.",
"hyper_inc.press_hn":"Un fil à ce sujet atteint 3 000 commentaires ; 2 000 disent qu'ils auraient auto-hébergé.",
"hyper_inc.press_postmortem":"Ton postmortem promet de ne blâmer personne. Le stagiaire n'en est pas si sûr.",
"hyper_inc.press_status":"Ta page de statut est restée verte tout du long. Personne n'y croit.",
"hyper_inc.press_trend":"« Le cloud est en panne ? » est en tendance mondiale.",
"hyper_inc.storm_dedupe":"Le service de déduplication de {city} a été dédupliqué. La réplication vers {b} renvoie tout, {x} fois plus que d'habitude.",
"hyper_inc.storm_flag":"Un push de config a inversé un flag à {city} : la région croit que sa réplique à {b} a tout oublié, et lui renvoie tout, {x} fois plus.",
"hyper_inc.storm_yaml":"Quelqu'un a indenté une ligne de YAML à {city}. La réplication vers {b} copie maintenant chaque objet {x} fois, par sécurité.",
"hyper_ops.l_az":{"one":"a ajouté une zone à {where}","other":"a ajouté {n} zones ({where})"},
