"hyper_ops.mood_bill":"{name} a ouvert le Cost Exploder, l'a refermé, et respire maintenant dans un sac en papier.",
"hyper_ops.mood_cat":"{name} a baptisé la nouvelle région du nom de son chat. Le chat n'est pas au courant.",
"hyper_ops.mood_cert":"{name} a mis un rappel pour renouveler les certificats TLS. Dans son agenda perso. Pour 2029.",
"hyper_ops.mood_serverless":"{name} a demandé si « serverless » veut dire qu'on peut rentrer plus tôt.",
"hyper_ops.mood_whiteboard":"{name} dessine encore des flèches de bascule au tableau. Certaines pointent vers la machine à café.",
"hyper_ops.o_az":"Découper les régions en zones",
"hyper_ops.o_az_d":"Une région qui a subi des pannes locales (un plantage, une coupure de courant, une faute de frappe dans un bâtiment) reçoit une autre zone de disponibilité, là où le niveau, les mégawatts et la loi le permettent. Une par service.",
"hyper_ops.o_drill":"Exercices de bascule",
"hyper_ops.o_drill_d":"Un exercice pour la paire de régions testée il y a le plus longtemps (d'abord celles jamais testées), un à la fois, jamais juste avant un gel de lancement.",
"hyper_ops.o_fund":"Répondre aux manifs",
"hyper_ops.o_fund_d":"Une manif que des fonds pour la commune gagneraient, jusqu'au prix ci-dessous, en reçoit jusqu'à ce qu'elle soit gagnée. La bienveillance ne déplace aucun trafic.",
"hyper_ops.o_rg":"Surveiller les régions",
"hyper_ops.o_rg_desc":"Une région au seuil ou au-delà passe au palier suivant, au plus une par mois et seulement vers un palier atteint il y a deux niveaux, si les mégawatts et la loi le permettent et que le mois reste bénéficiaire ; s'il manque du courant, on demande tôt au fournisseur d'électricité. Sinon, une note dans le rapport.",
"hyper_ops.o_wave":"Des waves pour le retard",
"hyper_ops.o_wave_desc":"Une paire de régions dont le retard de réplication dépasse le seuil reçoit une wave louée entre les deux, la plus petite qui porte ce qui manquait : une par service, puis une semaine pour résorber. Son prix mensuel compte dans le budget et ne fait jamais passer le mois en perte.",
"hyper_ops.p_days":"À nouveau après",
"hyper_ops.p_how":"Quand elle est pleine",
"hyper_ops.p_max":"Au plus par manif",
"hyper_ops.p_out":"Après",
"hyper_ops.p_ready":"Seulement si prête",
"hyper_ops.p_tb":"Retard au-delà de",
