"hyper_rivals.down_cert":"Un certificat que personne n'a renouvelé a fait tomber {rival} en {reg}. Leurs locataires t'appellent.",
"hyper_rivals.down_dns":"Un seul enregistrement DNS a fait tomber {rival} dans toute la zone {reg}. Leurs locataires t'appellent.",
"hyper_rivals.down_status":"La page d'état de {rival} pour {reg} est toute verte. Tout le reste est en feu. Leurs locataires t'appellent.",
"hyper_rivals.down_typo":"{rival} est en panne en {reg} : quelqu'un a mal tapé une commande pendant une maintenance de routine. Leurs locataires t'appellent.",
"hyper_rivals.job_coupon":"{lab} a confié son entraînement à {rival}, qui a ajouté un bon de 10 % sur le prochain.",
"hyper_rivals.job_gpus":"{rival} a pris l'entraînement de {lab} : « On a des GPU. Enfin, on en aura. »",
"hyper_rivals.job_thinking":"{rival} a pris l'entraînement de {lab} pendant que tu y réfléchissais.",
"hyper_rivals.poach_credits":"{name} est parti chez {rival} : « Ils nous ont promis 99,99999 % de disponibilité. Par écrit. En Comic Sans. »",
"hyper_rivals.poach_free_egress":"{name} est passé chez {rival} pour « l'egress gratuit ». Gratuit pour les trois premiers octets.",
"hyper_rivals.poach_hoodie":"{rival} t'a piqué {name} au renouvellement avec un sweat à son logo et un an de crédits gratuits.",
"hyper_rivals.poach_keynote":"{rival} t'a piqué {name} avec une keynote, une machine à fumée et une remise que personne ne sait expliquer.",
"hyper_rivals.war_blog":"{rival} baisse ses prix en {reg} de {p} et publie un billet sur « l'obsession du client ».",
"hyper_rivals.war_credits":"{rival} casse les prix du cloud en {reg} de {p} : « Maintenant avec 20 % de crédits gratuits en plus ! »",
"hyper_rivals.war_free_tier":"{rival} lance en {reg} une offre gratuite si gratuite qu'elle est {p} moins chère que la tienne.",
"hyper_rivals.win_credits":"{rival} a signé {name} avec un million de dollars de crédits gratuits qui expirent mardi.",
"hyper_rivals.win_donuts":"{rival} a signé {name} pendant que tu réfléchissais encore. Leur commercial a apporté des donuts.",
"hyper_rivals.win_golf":"{rival} a signé {name} sur le terrain de golf. Tu n'étais pas invité.",
"hyper_rivals.win_slides":"{rival} a remporté {name} avec 140 diapos et un sweat offert.",
"hyper_story.charter_desc":"Fais grandir un cloud, d'un rack sous l'escalier jusqu'à un système météo. Lance-toi dans des pays, ouvre des portes d'entrée, construis des régions là où sont les mégawatts et transporte chaque octet sur ton propre backbone. Des locataires louent des offres aux noms absurdes ; tu achètes du transit mais tu n'en vends jamais. Gagne Cloud Nine : des régions sur {ct} continents, un exercice réussi pour chaque paire de régions, ton propre câble à travers un océan et {g} entre régions à la pointe.",
