"ops.mood_annie":"Annie a répondu à trois questions avant que tu les poses, depuis le bureau le plus proche.",
"ops.mood_broke":"{name} a déjà sa liste de courses pour le budget du mois prochain.",
"ops.mood_busy":"{name} a eu une semaine chargée et en est à sa troisième boisson énergisante.",
"ops.mood_kevin":"Kevin dit que c'était plus calme en 2001. Ce n'était pas le cas.",
"ops.mood_new":"{name} a trouvé la machine à café et la CLI, dans cet ordre. Prêt quand tu veux.",
"ops.mood_oops":"{name} fait très attention aujourd'hui. Personne ne parle des descriptions d'interface.",
"ops.mood_outage":"{name} surveille les graphes de la panne et rafraîchit la page de statut. Beaucoup.",
"ops.mood_quiet":"{name} lit tranquillement des RFC. Les graphes sont plats, comme il se doit.",
"ops.mood_snag":"{name} est tombé sur un truc bizarre, a mis cet ordre en pause et t'a laissé un post-it.",
"ops.mood_tracy":"Tracy en est au troisième saut d'un traceroute, avec une seule étoile pour l'instant.",
"ops.o_caches":"Accepter les caches gratuits",
"ops.o_caches_d":"Installer chaque cache gratuit qu'un réseau propose, dès que son trafic dans la ville dépasse un seuil.",
"ops.o_decom":"Retirer les petits liens parallèles",
"ops.o_decom_d":"Dès qu'un plus gros lien relie deux villes, rendre les petites waves devenues inutiles. Jamais une qu'un client loue ou dont il dépend.",
"ops.o_fabric":"Agrandir vos exchanges",
"ops.o_fabric_d":"Améliorer la fabric d'un exchange que vous gérez quand son trafic dépasse la marge, ou quand toutes les places sont prises et qu'un réseau attend pour entrer. Une fabric plus grande transporte plus de trafic et accueille plus de membres payants.",
"ops.o_ix":"Peerer sur chaque IX",
"ops.o_ix_d":"Chaque semaine : rejoindre les route servers et solliciter chaque membre partant sur chacun de tes ports d'exchange.",
"ops.o_optics":"Allumer plus de fibre",
"ops.o_optics_d":"Ajouter des optiques sur la fibre noire qui chauffe, et allumer la nouvelle fibre le jour de sa livraison.",
"ops.o_optup":"Améliorer le transport optique",
"ops.o_optup_d":"Sur une fibre pleine qui chauffe, ou dont les acheteurs du marché de capacité veulent plus qu’elle ne peut vendre, passer le système de ligne à la taille au-dessus, ou échanger les plus petits canaux contre des optiques plus grandes (les anciennes partent sur l’étagère). Choisissez un système de ligne, et chaque fibre équipée d’un plus petit y passe. Un changement de système de ligne coupe la fibre pour une journée : seulement là où le trafic peut la contourner et où aucun client ne passe, un par nuit.",
"ops.o_pie":"Garder les croûtes pleines",
"ops.o_pie_d":"Réserve des lancements pour que vos croûtes restent pleines quand les vieilles tartes s'usent : tartes du stock de l'usine, premier pas de tir libre, jamais de vol d'essai. Chacun coûte ce que facture l'onglet Croûtes.",
"ops.o_pni":"PNI avec les gros",
"ops.o_pni_d":"Chaque semaine : commander un PNI avec chaque réseau partant qui envoie assez de trafic sur tes POP, à la taille minimale de chaque réseau.",
"ops.o_ports":"Garder de la marge sur les ports de peering",
"ops.o_ports_d":"Garder les ports PNI et IX au-dessus d'un multiple du trafic du jour : un port unique dans un POP à plusieurs routeurs en reçoit un deuxième en LAG, tous les autres passent à une taille de port au-dessus.",
"ops.o_repair":"Accélérer les réparations",
"ops.o_repair_d":"Payer la réparation express de chaque panne qui en a une, tant que le budget suit.",
"ops.o_routers":"Garder les routeurs en avance",
"ops.o_routers_desc":"Ajouter un routeur, ou passer à la génération suivante là où un second routeur porte le trafic, quand la charge ou les ports dépassent un seuil. Choisissez un modèle, et chaque POP équipé d’un plus petit passe à celui-ci, le plus chargé d’abord, dans la limite du budget.",
"ops.o_transit":"Garder de la marge de transit",
"ops.o_transit_d":"Garder le transit de chaque POP au-dessus d'un multiple de son pic sur 30 jours : un membre LAG de plus, ou une taille de port au-dessus.",
"ops.o_waveup":"Waves louées plus grandes",
"ops.o_waveup_d":"Monter une wave louée d'une taille quand elle chauffe, sauf si votre propre fibre noire passe déjà ou est en construction sur cette route.",
