"ops.tracy":"Tracy",
"ops.tracy_d":"Suit chaque paquet saut par saut. Arrive au bout, avec une ou deux étoiles en chemin.",
"ops.tracy_route":"Tracy Route",
"optx.l_d":"Des planificateurs, des soudeurs et un vétéran des câbles sous-marins qui a déjà vu chaque erreur une fois. Quatre routes à la fois, et rarement à côté.",
"optx.l_n":"Département de photonique",
"optx.m_d":"Une vraie équipe optique, avec un outil de planification et une camionnette. Deux routes à la fois.",
"optx.m_dark":"Quelqu'un s'est trompé dans une config : {where} est éteint jusqu'à demain.",
"optx.m_n":"L'Escouade Lambda",
"optx.m_over":"De la roche là où l'étude annonçait du sable sur {where} : les travaux coûtent {cost} de plus.",
"optx.m_slip":"Les permis pour {where} ont pris plus de temps : les travaux glissent de {n} jours.",
"optx.s_d":"Deux ingénieurs et une soudeuse à fibre. Une route à la fois, et rien n'est vérifié deux fois.",
"optx.s_n":"Une soudeuse et un tableur",
"oq":"San Salvador a un exchange mais personne dessus pour l’instant : le trafic entre deux FAI locaux sort donc généralement du pays pour se croiser.",
"or":"Le hub des câbles de la mer Rouge en Arabie saoudite. De plus en plus de câbles entre l’Europe, l’Afrique et l’Asie s’arrêtent ici plutôt qu’en Égypte.",
"os":"La capitale de l’Écosse. Les câbles de la mer du Nord vers la Norvège et les Féroé atterrissent un peu plus haut sur la côte.",
"ot":"Six réseaux dans la table de routage mondiale, et une passerelle qui porte l’essentiel du trafic du nord.",
"ou":"Petit, riche et très bien connecté. Sa seule frontière terrestre est avec l’Arabie saoudite.",
"ov":"Parmi les accès haut débit les plus rapides de la planète, et le marché du peering le plus étrange. Sous le régime « sender pays », les trois grands FAI facturent chaque gigabit qu’on leur remet, et le transit ici est parmi les plus chers au monde.",
"ow":"La côte est de l’Afrique du Sud : surf, curry et la plage où atterrissent les câbles de l’océan Indien.",
"own_cable.a_fishing_fleet_is_trawling_exactly":"Une flotte de chalutiers drague pile là où tu dois poser.",
"own_cable.a_whale_has_parked_on_the":"Une baleine s’est garée sur le tracé et refuse de bouger.",
"own_cable.storm_season_the_ship_is_sheltering":"Saison des tempêtes. Le navire s’abrite au port et joue aux cartes.",
"own_cable.the_cable_ship_s_coffee_machine":"La machine à café du câblier est en panne. Personne ne bosse sans café.",
"own_cable.the_crew_fished_out_somebody_else":"L’équipage a repêché le câble de quelqu’un d’autre par erreur et doit le remettre.",
"own_cable.the_seabed_survey_found_an_old":"L’étude des fonds marins a trouvé une vieille mine. Un petit détour, très prudent.",
"ox":"Le plus grand marché d’Amérique du Sud, et le berceau d’IX.brrr : géré par une association à but non lucratif, prix publics, et presque tout le monde y est.",
"oy":"Règles d’Internet souverain : chaque POP doit héberger un boîtier du gouvernement dans la baie, les vidéos Goggle sont bridées, et le pare-feu national fait des exercices.",
"oz":"Startups, techno et un nombre surprenant de datacenters dans d’anciennes brasseries.",
"p":"{city} s’éteint",
"p0":"Les câbles sous-marins vers l’Afrique et l’Asie atterrissent ici.",
"p1":"Le premier câble du Suriname touche terre à Totness, à deux heures à l’ouest sur la côte, et continue vers le Guyana et Trinidad.",
"p2":"La côte ouest de la Suède, à mi-chemin entre Oslo et Copenhague : la fibre entre la Suède et la Norvège passe par ici.",
"p3":"La ville fédérale suisse gouverne d’ici et peere depuis Zurich, à une heure de train.",
"p4":"Tahiti, en Polynésie française. Un câble remonte vers Hawaï, et le nouveau, du Chili à l’Australie, s’y arrête : le gué entre l’Amérique du Sud et l’Océanie.",
"p5":"Tango, steak et une foule très fidèle de FAI locaux.",
"p6":"La plus grande ville de Tanzanie et la porte sur la mer d’une demi-douzaine de pays enclavés.",
"p7":"Le premier câble de Tarawa est arrivé en 2026 : deux mille kilomètres jusqu’à Nauru et Pohnpei, payés par trois gouvernements amis.",
"p8":"La capitale de la pêche des Aléoutiennes. La fibre est arrivée en 2023 ; avant, c’était satellites et patience.",
"p9":"Les Açores, au milieu de l’Atlantique. Les câbles de la Floride vers Lisbonne et l’Espagne y font escale : un POP coupe la traversée en deux et chaque moitié transporte davantage. Les vaches sont plus nombreuses que les serveurs.",
"pa":"La capitale des Bahamas, à un saut de la Floride. La plupart des câbles vers le sud s’y arrêtent en chemin.",
"pb":"La plus grande ville au nord du cercle polaire arctique. Le câble russe Polar Express devait partir d’ici vers l’est ; seul le premier tronçon est à l’eau. Pose le tien.",
"pc":"Le bout du pays, sur des lignes électriques construites pour une fonderie d’aluminium. Quelqu’un construit un campus IA de 280 MW dans un pré à la sortie de la ville, donc les câbles vont arriver. Probablement.",
"pd":"Le bas de la carte. De l’air frais, de l’hydroélectricité bon marché, et tout le détroit de Bass entre toi et le continent.",
"pe":"La capitale économique de l’Afrique de l’Ouest francophone, avec des tours de verre sur une lagune et cinq câbles dans la baie.",
"peering_desk.closed_desc":"Toute demande de peering est déclinée, et pas de route servers. Les clients entendent dire que tu es difficile à joindre, donc moins d’entre eux appellent.",
"peering_desk.open_desc":"Tout réseau qui demande obtient une session, et les route servers fonctionnent.",
"peering_desk.open_to_all":"Ouverte à tous",
"peering_desk.selective_desc":"Les petits réseaux de l’exchange et les nouveaux venus avec un PeeringDB à jour obtiennent une session ; les autres sont discrètement déclinés. Pas de route servers : va demander les réseaux que tu veux sur chaque exchange.",
"pf":"Les Canaries, à un saut de Lisbonne et du Maroc. Presque tous les câbles qui longent la côte ouest de l’Afrique y font escale, et le long trajet jusqu’à Lagos devient deux trajets plus courts.",
"pg":"La capitale, qui construit des campus IA à l’échelle du gigawatt. Les données des utilisateurs saoudiens doivent rester dans le Royaume, et chaque POP exige une licence télécom locale.",
"ph":"La capitale est ici, l’internet à trente kilomètres, à Cotonou, où atterrissent les câbles et tourne l’exchange.",
"pi":"La capitale de l’Acre, un État dont les Brésiliens disent en plaisantant qu’il n’existe pas. Tes traceroutes disent le contraire.",
"pie.co_compensation_dynamics":"Compensation Dynamics",
"pie.co_escape_velocity_partners":"Escape Velocity Partners",
"pie.co_gravity_is_optional":"Gravity Is Optional",
"pie.co_hubris_heavy_industries":"Hubris Heavy Industries",
"pie.co_mid_life_crisis_aerospace":"Mid-Life Crisis Aerospace",
"pie.co_payload_bearing":"Payload Bearing",
"pie.co_spacexpensive":"SpaceXpensive",
