"pj":"La capitale des Îles Marshall, un anneau de corail à deux mètres au-dessus de la mer. Un seul câble vers Guam, et chaque paquet le sait.",
"pk":"L’exchange de la capitale est petit : celui qui compte au Honduras est à San Pedro Sula, la ville des usines au nord.",
"pl":"La capitale. De l’argent souverain pour l’IA et de très gros datacenters. Aux Émirats, seuls les deux opérateurs agréés ont le droit de déployer de la fibre.",
"pm":"La capitale écrit les règles d’Internet, puis garde les serveurs à côté : les data centers sont à une demi-heure, à Ashburn, alors la ville elle-même est un petit marché aux utilisateurs très importants.",
