"pv":"La Cité-Jardin, et la plus grande ville de l’île du Sud, que les gens d’ici appellent « le Continent » sans rire. Tout ce qui part vers l’île du Nord traverse le détroit de Cook.",
"pw":"La passerelle de la moitié de l’Asie centrale : réseaux tadjiks, turkmènes et afghans achètent tous via Tachkent.",
"px":"Le centre géographique de l’Amérique du Sud, et l’une des villes les plus chaudes du Brésil. Les groupes froids n’ont jamais de jour de repos.",
"py":"Le centre géographique des États-Unis. Les datacenters sont installés dans d’anciennes mines de calcaire souterraines : température stable, pas de tornades, et quelqu’un n’arrête pas de retrouver les souliers de Dorothy.",
"pz":"Le gouvernement est monté à Gitega en 2019 ; l’exchange et les datacenters sont restés à Bujumbura.",
"q":"Il manque {g} à {city}",
"q0":"Le port, le pont et la plupart des data centers du pays. La vraie latence, c’est le loyer.",
"q1":"Le siège de gouvernement le plus haut du monde, à 3 600 m. Les pendulaires prennent le téléphérique, et une partie de la fibre aussi.",
"q2":"Le long trajet jusqu’à Johannesburg : le trafic de Djouba parcourt des milliers de kilomètres avant de croiser l’essentiel d’internet.",
"q3":"La capitale des Maldives, à un mètre au-dessus de la mer, escale des câbles de l’Inde vers le Golfe et Singapour.",
"q4":"Le milieu de partout : pas de mer, pas de câble, juste de la fibre le long de l’autoroute et une vieille station télégraphique.",
"q5":"La grande ville la plus isolée de la planète. L’Asie est plus proche que Sydney.",
"q6":"Le hub du Nord, avec son propre IX et des prises d’air de clim très humides. Les câbles vers l’Irlande et le Danemark atterrissent un peu plus haut sur la côte.",
"q7":"La ville la plus au nord des États-Unis, desservie par la première fibre sous-marine de l’Arctique américain.",
"q8":"La capitale des Territoires du Nord-Ouest, au bout de la fibre de la vallée du Mackenzie, posée le long du fleuve jusqu’à la côte arctique.",
"q9":"L’ancienne porte de l’Europe de l’Est. Les paquets s’inclinent encore poliment en passant.",
"qa":"La seule capitale du Nordeste loin de la mer. Réputée pour sa chaleur, avec des orages qui donnent du travail aux parafoudres.",
"qb":"La porte du Pacifique. Les Andes la séparent de tout le reste, et la terre tremble de temps en temps.",
"qc":"La deuxième ville des Philippines, joignable uniquement par câble national. Les typhons y passent en remontant vers le nord.",
"qd":"La porte des Prairies entre Vancouver et le reste du Canada. Un chinook fait fondre la neige en un après-midi, puis il reneige.",
"qe":"Le hub de la Rhénanie-Ruhr : plus de data centers neutres que Hamburg ou Munich, et à une heure de la frontière néerlandaise, donc la fibre vers Amsterdam est courte et pas chère. Ici, on commande une Altbier, jamais une Kölsch.",
"qf":"La capitale des Seychelles, sur Mahé : 115 îles, des tortues géantes et deux câbles vers le continent.",
"qg":"La capitale des Îles Salomon, sur Guadalcanal. Le câble vers Sydney n’est arrivé qu’il y a quelques années ; avant, tout passait par satellite. Le courant est moins fiable que le câble.",
"qh":"Le carrier hotel du Sud-Est. L’aéroport le plus fréquenté, le peering le plus fréquenté au sud d’Ashburn.",
"qi":"C'est ici, sur la côte basque, qu'arrivent les câbles transatlantiques. L'exchange est à Madrid, donc presque tout le trafic file vers l'intérieur des terres.",
"qj":"La Venise du Brésil, toute en ponts et en rivières, avec l’un des plus grands parcs technologiques du pays dans son vieux port.",
"qk":"Tout le pays est un seul réseau qui annonce une poignée de routes, et les foyers ordinaires n’y sont pas raccordés.",
"ql":"Tout le pays sur un seul câble : une branche d’ACE, atterrie en 2011 et partagée par tous les opérateurs.",
"qm":"La capitale du Yukon, sur une seule longue fibre le long de la route de l’Alaska : une coupure au sud de la ville et tout le territoire attend.",
"qn":"Organise la plus grande fête de São João du monde : un mois entier de forró chaque juin. Aussi une ville universitaire pleine d’ingénieurs.",
"qo":"Le premier câble du Timor oriental a été allumé en juillet 2026 : six cents kilomètres jusqu’au North-West Cable System australien.",
"qp":"Minuscule, tropicale et la ville australienne la plus proche de l’Asie. De nouveaux câbles vers Singapore et Jakarta atterrissent ici, à côté des crocodiles.",
"qq":"Les Tonga tiennent à un seul câble depuis les Fidji. En 2022, un volcan sous-marin l’a coupé et le pays est resté hors ligne pendant des semaines.",
"qr":"La capitale de Trinidad, au bout sud de l’arc des îles et à quelques kilomètres du Venezuela.",
"qs":"Douze mille habitants et leur premier câble, atterri en août 2025 en route de Tarawa vers Pohnpei.",
"qt":"À vingt minutes de tout, sauf de n’importe où ailleurs.",
"qu":"Villes jumelles, un seul exchange et des passerelles entre les immeubles : Minneapolis peere ici aussi, et en janvier personne ne sort souder une fibre.",
"qv":"À deux heures au nord de Stockholm, une région cloud et une célèbre chèvre de paille.",
"qw":"Deux millions d’habitants au milieu de la forêt tropicale, avec une zone franche industrielle. La fibre suit les fleuves, et quand elle casse, l’équipe de réparation part en bateau.",
"qx":"Deux exchanges rivaux, l’un à l’université technique, l’autre commercial, et la plupart des réseaux slovaques sont sur les deux.",
"qy":"Typhons, séismes et beaucoup de gens très connectés.",
"qz":"Les ingénieurs réseau ukrainiens ont fait tourner Internet malgré les coupures de courant et bien pire. Groupes électrogènes, fibre de secours et redondance partout sont la norme ici, et la scène peering est réputée coriace.",
"r":"Fermé",
"r0":"Universités, biotech et un carrier hotel qui a survécu à la plupart de ses opérateurs.",
"r1":"L’Uruguay : la fibre dans presque chaque foyer, un ordinateur portable pour chaque écolier, et un opérateur public qui gère presque tout.",
"r2":"Très connectée et mal desservie par la mer : à tout moment, au moins un de ses câbles sous-marins est coupé.",
"r3":"La capitale de la Virginie, où les câbles transatlantiques de Virginia Beach arrivent à l’intérieur des terres vers un exchange neutre : une entrée en Europe plus calme qu’Ashburn.",
"r4":"La chaleur fatale part directement dans les thermes d’à côté.",
"r5":"Les plaines de l’ouest du Texas, du terrain bon marché et un gigawatt d’entraînement IA qui y pousse.",
"r6":"Quand son unique câble a été coupé en 2018, la Mauritanie a été presque entièrement hors ligne pendant deux jours.",
"r7":"Quand le câble est arrivé en 2025, tout le pays a eu Internet gratuit pendant une journée pour fêter ça.",
"r8":"Là où se rejoignent le Brésil, l’Argentine et le Paraguay, à côté de chutes géantes et d’un barrage hydroélectrique encore plus grand. L’électricité est bon marché, la paperasse douanière non.",
"r9":"Là où les câbles d’Afrique de l’Est touchent terre, avant de remonter par le chemin de fer jusqu’à Nairobi.",
"ra":"Là où le vent de la mer du Nord et l’électricité sous-marine touchent terre, un campus cloud derrière la digue.",
"rb":"Là où les câbles d’Amérique du Sud atterrissent vraiment. L’Europe, l’Afrique et les États-Unis touchent terre ici, puis empruntent un long backhaul vers le sud.",
"rc":"Là où atterrissent les câbles atlantiques vers le sud de l’Afrique. Des manchots sur la plage, du délestage sur le réseau électrique.",
"rd":"Des maisons blanches qui grimpent depuis la Méditerranée. Les câbles partent au nord vers Marseille, et une bonne partie du trafic aussi.",
"re":"Des parcs éoliens et de l’air froid au nord de Pékin : les campus cloud de la capitale.",
