"sales.auto_ceo":"{name} signe les offres que votre réseau peut servir aujourd'hui, un essai par jour. Il refuse aussi celles sous votre minimum, même si de temps en temps il a déjà topé.",
"sales.auto_eng":"{name} signe les offres que votre réseau peut servir aujourd'hui, après avoir essayé chacune sur le réseau (une par jour), et refuse celles qui paient moins que votre minimum.",
"sales.auto_shark":"{name} signe chaque offre dès qu'elle arrive, promesses comprises, tant que vous pouvez payer la commission, et refuse celles qui paient moins que votre minimum.",
"sales.ceo_d":"Gratuit, et convaincu. Tous les deux mois, il signe un énorme contrat sur le terrain de golf à -30 %, souvent avec une promesse que personne n'a vérifiée, et de temps en temps une offre que vous aviez refusée. A des avis sur tout. Impossible à licencier.",
