"sales.ceo_say_airport":"Je viens d'atterrir. Rien signé, mais j'ai eu un très bon pressentiment avec le Wi-Fi du salon.",
"sales.ceo_say_blockchain":"Avons-nous pensé à mettre la table de routage sur une blockchain ?",
"sales.ceo_say_golf":"Les meilleurs contrats se signent au neuvième trou. Le NOC devrait jouer plus au golf.",
"sales.ceo_say_mbps":"Pourquoi vendre des gigabits ? Des mégabits, ça fait plus.",
"sales.ceo_say_napkin":"J'ai chiffré le prochain contrat sur une serviette. L'ingénierie réglera les détails.",
"sales.ceo_say_synergy":"Nous ne vendons pas de la bande passante, nous vendons de la synergie. Mettez ça sur le site.",
"sales.ceo_sky":"En orbite : une partie de golf sur deux se joue avec le Fondateur, pour le plus gros contrat en orbite qui rentre, à -30 %. Les marchés nerveux lui coûtent : des prix plus bas en orbite, et pas de golf du tout quand ils sont très nerveux.",
"sales.eng_d":"Ancien ingénieur réseau, il a un badge de chaque NOG. Il vous inscrit à toutes (vous payez le billet), apporte beaucoup de petits et moyens contrats mais jamais les très gros, et ne vend que ce que le réseau sait faire : les clients restent. Les geeks adorent Dave. Il négocie mal.",
"sales.eng_n":"L'ingénieur devenu commercial-droïde",
"sales.eng_s":"Dave",
"sales.eng_sky":"En orbite : ne vend que là où l'antenne d'atterrissage a de la marge, et ces clients restent comme les geeks.",
"sales.ren_ceo":"{name} répond à la renégociation d'un client trois jours après son début, sur le terrain de golf : une remise plus forte que demandé contre un contrat deux fois plus long, un oui rapide, ou une dispute après laquelle le client s'en va.",
"sales.ren_ceo_fight":"{name} a dit à {cust} que personne ne négocie avec lui. Ils sont partis.",
"sales.ren_ceo_yes":"{name} a dit oui à {cust} avant que quiconque puisse vérifier : {price}/mois.",
"sales.ren_eng":"{name} répond à la renégociation d'un client trois jours après son début. Les clients geeks ont droit à un après-midi avec les schémas du réseau et renouvellent le plus souvent au prix du marché ; les autres obtiennent la remise demandée. Personne ne part.",
"sales.ren_eng_cave":"{name} a accordé à {cust} la remise demandée : {price}/mois. Ils restent.",
"sales.ren_eng_tech":"{name} a passé un après-midi à montrer le réseau aux ingénieurs de {cust}. Ils renouvellent à {price}/mois, sans remise.",
"sales.ren_mid":"{name} a coupé la poire en deux avec {cust} : {price}/mois.",
"sales.ren_shark":"{name} répond à la renégociation d'un client trois jours après son début, et ne lâche rien : la plupart renouvellent à l'ancien prix, souvent avec une nouvelle promesse, et il vous facture un mois de ce qu'il vous a fait gagner. Certains partent, surtout les geeks.",
"sales.ren_shark_walk":"{name} a joué les durs avec {cust}, et ils sont partis.",
"sales.shark_d":"Décroche les plus gros contrats un quart plus cher, et prend un mois de chaque contrat en commission. Survend : la moitié arrive avec une promesse que votre réseau ne tient pas encore, et ces clients partent plus tôt. Ignore les geeks : pas de clients techniques, pas de NOG, et les équipes peering vous demandent un quart de trafic en plus. Gagne la plupart des négociations.",
"sales.shark_n":"Le requin",
"sales.shark_s":"Chad",
"sales.shark_sky":"En orbite : appelle d'abord les compagnies aériennes et les croisières, à la plus grande taille et un quart plus cher, et promet à la moitié un ciel plein avant que vous l'ayez. Ils râlent jusqu'à ce que ce soit le cas.",
"sb":"Démanteler plusieurs POP…",
"sc":"Glisse depuis ce routeur vers n’importe quelle ville de la carte pour tirer un nouveau lien. Deux chemins vers chaque POP, et aucune pelleteuse ne pourra te couper du monde.",
"sd":"Tous les ports sont pris. Ajoute un routeur ou passe à un modèle avec plus de ports avant de brancher quoi que ce soit.",
"se":"Tout est dans un seul bâtiment. Déplace des uplinks vers l’autre site depuis les onglets Transit et Peering.",
"sf":"Fabrics : {list}",
"sg":"Peu de data centers : POP {x}×",
"sh":"Fibre depuis {city}",
"si":"fibre en panne",
"sj":"Les flots visant ici sont attirés vers ton centre de scrubbing à {city}, à {km} km. Le trafic propre revient par ton backbone, ce qui ajoute de la latence. Un centre ici raccourcit le détour.",
