"sold_out.a_hyperscaler_bought_every_wave_of":"Un hyperscaler a acheté la semaine dernière toutes les ondes de cette taille sur cette route.",
"sold_out.the_capacity_is_available_in_the":"La capacité est « disponible dans le système ». Personne ne la trouve dans le système.",
"sold_out.the_carrier_is_out_of_spectrum":"L’opérateur n’a plus de spectre ici jusqu’à la prochaine mise à niveau du système de ligne.",
"sold_out.the_transponders_for_this_route_are":"Les transpondeurs pour cette route sont sur un porte-conteneurs. Le navire est quelque part près de Singapour.",
"sold_out.the_upgrade_is_planned_for_q3":"La mise à niveau est prévue pour le T3. De quelle année, l’e-mail ne le dit pas.",
"sold_out.their_capacity_planner_is_on_holiday":"Leur planificateur de capacité est en vacances, et il a emporté le tableur.",
"sp":"Fabrics d’interconnexion (NNI)",
"specialist.cable_broker":"Courtier en câbles",
"specialist.cable_broker_desc":"Pose de la fibre sur terre et des câbles sous la mer dès le premier jour, allume-les et vends la capacité à d’autres opérateurs. Des objectifs à lui ; gagne Baron du Verre : tes propres câbles atterrissent sur {n} continents pendant que les opérateurs te paient {m} par mois. Tout le reste se débloque par niveau, comme toujours.",
"specialist.global_backbone":"Backbone mondial",
"specialist.low_latency_boutique":"Boutique basse latence",
"specialist.spotted_your_broadband_in_a_one":"Ils ont repéré ton haut débit à {a}, une des grandes villes d'abonnés.",
"specialist.spotted_your_cap_of_dark_fiber":"Ils ont repéré tes {cap} de fibre noire allumée entre {a} et {b}.",
"specialist.spotted_your_ms_ms_a_b_path":"Ils ont repéré ton chemin {a}–{b} à {ms} ms.",
"specialist.spotted_your_two_diverse_paths_a":"Ils ont repéré tes deux chemins diversifiés entre {a} et {b}.",
"specialist.the_classic_game_grow_everywhere_and":"Le jeu classique : grandis partout, les clients suivent ton niveau, et Tier 1 est la victoire.",
"specialist.trading_firms_and_other_latency_customers":"Les sociétés de trading et autres clients latence appellent plus souvent et paient {p} % de plus. Gagne Vitesse de la lumière : bats la latence louée la plus rapide sur {r} routes financières avec ta propre fibre pendant que {c} clients latence te paient. Tier 1 compte toujours.",
"sq":"Ça passe par ta propre fibre, donc le Nearly Broadband Network ne touche rien. Le gouvernement prélève quand même une taxe de {pct}.",
"sr":"IX : <b>{ix}</b>",
"ss":"Membres de l’IX sur {ix} : {n}",
"st":"Switch {ix}",
"su":"Lancer le haut débit <small>{cost}</small>",
"supply_chain.chip_shortage_every_router_vendor_is":"<b>Pénurie de puces !</b><br>Tous les fabricants de routeurs attendent les mêmes puces. Les routeurs neufs et les mises à niveau coûtent 40 % de plus pendant {n} jours. Délai de livraison : « oui ».",
"supply_chain.every_cable_ship_is_booked":"<b>Tous les câbliers sont réservés.</b><br>Les hyperscalers ont loué chaque câblier et chaque équipe de tranchée de la planète. Les nouvelles fibres et les nouveaux câbles coûtent 30 % de plus pendant {n} jours.",
"supply_chain.laser_shortage_the_factory_that":"<b>Pénurie de lasers !</b><br>L’usine qui fabrique les lasers de la moitié des optiques du monde a été inondée. Les optiques coûtent 50 % de plus pendant {n} jours. Les pièces de rechange sur votre étagère viennent de devenir le meilleur investissement de votre vie.",
"supply_chain.new_fiber_and_cable_builds":"Nouvelles fibres et nouveaux câbles",
