"te":"Un seul routeur, c’est un point de défaillance unique.",
"tf":"Ici, ils ne vendent que leur traversée premium CN-Too, par voie terrestre jusqu’en Chine : prix de Hong Kong, environ 3 % de perte vers la Chine, et rien d’autre.",
"tg":"Ouvrir un POP ici",
