"ti":"Commander le circuit quand même",
"tj":"Peering payant : {price}/mois en plus",
"tk":"Paie un plus gros réseau au Gbps et il transporte ton trafic vers tout Internet. Facturé au 95e percentile des 30 derniers jours, avec un engagement de 20 % et des frais de port. Les pics comme les DDoS font grimper ta facture.",
