"tq":"Les prix incluent {p} récupérés en revendant les anciens routeurs sur eBuy.",
"tr":"Interconnexions privées (PNI)",
"ts":"Une fois activé, il annonce la cible de façon plus spécifique : les flots arrivent sur sa propre entrée de {g} au lieu de tes ports, et il les nettoie. Le trafic propre revient par ton backbone. Il débloque aussi les contrats de protection DDoS.",
"tt":"prêt dans {n} j",
"tu":"Vraiment le fermer ?",
"tv":"Vraiment l’arrêter ?",
"tw":"Remote peering sur l’IX",
"tx":"Pour l’instant, {city} tient dans un seul bâtiment. Une coupure de courant, une clim en panne ou un agent d’entretien avec son aspirateur, et toute la ville est dans le noir : un second routeur n’y change rien. Un second datacenter à l’autre bout de la ville, relié par ton propre anneau métropolitain, garde la moitié du POP en ligne.",
"ty":"Mise à niveau progressive : un routeur à la fois, zéro coupure.",
"tz":"Routeur saturé",
"u":"D’une côte à l’autre",
"u0":"Lancer une campagne de pub <small>$8k · croissance 2× pendant 30 j</small>",
"u1":"Second site et anneau métropolitain",
"u2":"Vends de l’Internet aux foyers d’ici. Démarre vers {start} et grimpe vers {max} tant que le service est bon. Rapporte {rate} par Gbps servi, chaque mois.",
"u3":"vend des PNI dès 1G",
