"u5":"Servi à {city}",
"u6":"dessert {v}",
"u7":"Ferme ce POP : ses liens, ports et caches partent avec, et chaque client qui en dépend est lâché, avec une pénalité de résiliation anticipée.",
"u8":"Passer en toujours actif",
"u9":"Passer à CN-Too premium <small>prix {x}× · ~3 % de pertes vers la Chine</small>",
"ua":"Passer à la demande <small>moins cher</small>",
"ub":"Le modèle détermine ton interface la plus rapide et ce que ce POP peut transmettre. Plus de routeurs, c’est plus de capacité et une meilleure résistance aux plantages.",
"uc":"Le Nearly Broadband Network en garde {pct} pour le dernier kilomètre.",
"ud":"La cage standard accueille {n} routeurs. Chacun au-delà demande une extension : l'installation coûte 50 % de plus et {mo}/mois en plus pour l'espace et l'énergie.",
"ue":"Ce châssis met une éternité à booter : les plantages durent plus longtemps, et remplacer l’unique routeur d’ici prend 3 jours. Un second routeur masque le problème.",
"uf":"Ce POP a {n} routeurs, autant que le bâtiment peut alimenter. Passez à un modèle plus gros pour aller plus loin.",
