"uj":"Transit {x}× plus cher",
"uk":"Deux bâtiments reliés par ton propre anneau métropolitain. Une coupure de courant ou un agent d’entretien dans l’un laisse l’autre tourner à mi-capacité. Les uplinks ne marchent que si leur site est debout, sauf si tu les répartis : choisis <b>Les deux</b> sur un port pour mettre des membres LAG dans chaque bâtiment.",
